static char __builtin_stddef_h[469] = "/* stddef.h - standard definitions for CCCC C compiler */\n\n#ifndef __STDDEF_H\n#define __STDDEF_H\n\ntypedef long ptrdiff_t;\ntypedef unsigned long size_t;\ntypedef int wchar_t;\n\n#if __STDC_VERSION__ >= 202311L\ntypedef typeof(nullptr) nullptr_t;\n#define unreachable() __builtin_unreachable()\n#endif\n\n#define NULL ((void*)0)\n\n/* offsetof macro - works with standard layout structs */\n#define offsetof(type, member) ((size_t) &(((type *)0)->member))\n\n#endif /* __STDDEF_H */\n";
static char __builtin_stdint_h[1649] = "/* stdint.h - fixed-width integer types for CCCC C compiler */\n\n#ifndef __STDINT_H\n#define __STDINT_H\n\n/* On this VM, long is 8 bytes */\ntypedef signed char int8_t;\ntypedef short int16_t;\ntypedef int int32_t;\ntypedef long int64_t;\n\ntypedef unsigned char uint8_t;\ntypedef unsigned short uint16_t;\ntypedef unsigned int uint32_t;\ntypedef unsigned long uint64_t;\n\ntypedef long intptr_t;\ntypedef unsigned long uintptr_t;\n\ntypedef long intmax_t;\ntypedef unsigned long uintmax_t;\n\n#define INTPTR_MIN  (-9223372036854775807L-1)\n#define INTPTR_MAX  9223372036854775807L\n#define UINTPTR_MAX 18446744073709551615UL\n\n#define INTMAX_MIN  (-9223372036854775807L-1)\n#define INTMAX_MAX  9223372036854775807L\n#define UINTMAX_MAX 18446744073709551615UL\n\n#define INT8_MIN   (-128)\n#define INT8_MAX   127\n#define INT16_MIN  (-32768)\n#define INT16_MAX  32767\n#define INT32_MIN  (-2147483648)\n#define INT32_MAX  2147483647\n#define INT64_MIN  (-9223372036854775807L-1)\n#define INT64_MAX  9223372036854775807L\n\n#define UINT8_MAX  255\n#define UINT16_MAX 65535\n#define UINT32_MAX 4294967295U\n#define UINT64_MAX 18446744073709551615UL\n\n/* 7.18.4 Macros for integer constants.\n * Append the suffix that gives a constant of at least the requested width.\n * On the CCCC target, long long / unsigned long long are 64-bit, so the\n * 64-bit and maximum-width forms use the LL / ULL suffixes. */\n#define INT8_C(x)    x\n#define INT16_C(x)   x\n#define INT32_C(x)   x\n#define INT64_C(x)   x ## LL\n#define UINT8_C(x)   x\n#define UINT16_C(x)  x\n#define UINT32_C(x)  x ## U\n#define UINT64_C(x)  x ## ULL\n#define INTMAX_C(x)  x ## LL\n#define UINTMAX_C(x) x ## ULL\n\n#endif /* __STDINT_H */\n";
static char __builtin_stdio_h[3950] = "/*\n * stdio.h - Standard I/O functions for CCCC VM\n */\n\n#ifndef __STDIO_H\n#define __STDIO_H\n\n#include \"stdarg.h\"\n#include \"stddef.h\"\n\n// FILE type (opaque pointer to host FILE)\ntypedef void FILE;\n\n// Standard streams (accessed via getter functions)\nextern FILE* __cccc_stdin(void);\nextern FILE* __cccc_stdout(void);\nextern FILE* __cccc_stderr(void);\n#define stdin __cccc_stdin()\n#define stdout __cccc_stdout()\n#define stderr __cccc_stderr()\n\n/* Types and macros from the C standard */\ntypedef long fpos_t;\n\n/* Buffering and limits */\n#ifndef BUFSIZ\n#define BUFSIZ 8192\n#endif\n\n#ifndef EOF\n#define EOF (-1)\n#endif\n\n#ifndef FILENAME_MAX\n#define FILENAME_MAX 4096\n#endif\n\n#ifndef FOPEN_MAX\n#define FOPEN_MAX 20\n#endif\n\n#ifndef L_tmpnam\n#define L_tmpnam 20\n#endif\n\n#ifndef TMP_MAX\n#define TMP_MAX 238328\n#endif\n\n/* Seek constants */\n#ifndef SEEK_SET\n#define SEEK_SET 0\n#define SEEK_CUR 1\n#define SEEK_END 2\n#endif\n\n/* setvbuf modes */\n#ifndef _IOFBF\n#define _IOFBF 0\n#define _IOLBF 1\n#define _IONBF 2\n#endif\n\n// ==================================================\n// Variadic function declarations \n// ==================================================\n// Supported via platform inline assembly\n\n// Printf family\nextern int printf(const char *fmt, ...)\n    __attribute__((format(printf, 1, 2)));\nextern int fprintf(FILE *stream, const char *fmt, ...)\n    __attribute__((format(printf, 2, 3)));\nextern int sprintf(char *str, const char *fmt, ...)\n    __attribute__((format(printf, 2, 3)));\nextern int snprintf(char *str, size_t size, const char *fmt, ...)\n    __attribute__((format(printf, 3, 4)));\n\n// Scanf family\nextern int scanf(const char *fmt, ...)\n    __attribute__((format(scanf, 1, 2)));\nextern int sscanf(const char *str, const char *fmt, ...)\n    __attribute__((format(scanf, 2, 3)));\nextern int fscanf(FILE *stream, const char *fmt, ...)\n    __attribute__((format(scanf, 2, 3)));\n\n// V* variants (take va_list) - Note: va_list manipulation not fully supported in VM\n// These are provided for completeness but may not work as expected\nextern int vprintf(char *fmt, va_list ap);\nextern int vsprintf(char *str, char *fmt, va_list ap);\nextern int vsnprintf(char *str, long size, char *fmt, va_list ap);\nextern int vfprintf(FILE *stream, char *fmt, va_list ap);\nextern int vscanf(char *fmt, va_list ap);\nextern int vsscanf(char *str, char *fmt, va_list ap);\nextern int vfscanf(FILE *stream, char *fmt, va_list ap);\n\n// ==================================================\n// Common non-variadic stdio functions (both modes)\n// ==================================================\n\n\nextern int remove(const char* filename);\nextern int rename(const char* old, const char* new);\nextern FILE* tmpfile(void);\nextern char* tmpnam(char* s);\nextern int fclose(FILE* stream);\nextern int fflush(FILE* stream);\nextern FILE* fopen(const char* filename, const char* mode);\nextern FILE* freopen(const char* filename, const char* mode, FILE* stream);\nextern void setbuf(FILE* stream, char* buf);\nextern int setvbuf(FILE* stream, char* buf, int mode, size_t size);\nextern int fgetc(FILE* stream);\nextern char* fgets(char* s, int n, FILE* stream);\nextern int fputc(int c, FILE* stream);\nextern int fputs(const char* s, FILE* stream);\nextern int getc(FILE* stream);\nextern int getchar(void);\nextern int putc(int c, FILE* stream);\nextern int putchar(int c);\nextern int puts(const char* s);\nextern int ungetc(int c, FILE* stream);\nextern size_t fread(void* ptr, size_t size, size_t nmemb, FILE* stream);\nextern size_t fwrite(const void* ptr, size_t size, size_t nmemb, FILE* stream);\nextern int fgetpos(FILE* stream, fpos_t* pos);\nextern int fseek(FILE* stream, long int offset, int whence);\nextern int fsetpos(FILE* stream, const fpos_t* pos);\nextern long int ftell(FILE* stream);\nextern void rewind(FILE* stream);\nextern void clearerr(FILE* stream);\nextern int feof(FILE* stream);\nextern int ferror(FILE* stream);\nextern void perror(const char* s);\n\n#endif // __STDIO_H\n";
static char __builtin_stdlib_h[3866] = "// Standard library function declarations for FFI\n// This header provides declarations for C standard library functions\n// that are registered in the VM's FFI and can be called directly\n\n#ifndef __STDLIB_H\n#define __STDLIB_H \n\n#include \"stddef.h\"\n\n/* EXIT macros */\n#ifndef EXIT_SUCCESS\n#define EXIT_SUCCESS 0\n#endif\n#ifndef EXIT_FAILURE\n#define EXIT_FAILURE 1\n#endif\n\n// typedef unsigned int once_flag;\n// extern void call_once(once_flag* flag, void (*func)(void));\n\nextern double atof(const char* nptr);\nextern int atoi(const char* nptr);\nextern long int atol(const char* nptr);\nextern long long int atoll(const char* nptr);\n// extern int strfromd(char* s, size_t n, const char* format, double fp);\n// extern int strfromf(char* s, size_t n, const char* format, float fp);\n// extern int strfroml(char* s, size_t n, const char* format, long double fp);\nextern double strtod(const char* nptr, char** endptr);\nextern float strtof(const char* nptr, char** endptr);\nextern long double strtold(const char* nptr, char** endptr);\nextern long int strtol(const char* nptr, char** endptr, int base);\nextern long long int strtoll(const char* nptr, char** endptr, int base);\nextern unsigned long int strtoul(const char* nptr, char** endptr, int base);\nextern unsigned long long int strtoull(const char* nptr, char** endptr, int base);\n\nextern int rand(void);\nextern void srand(unsigned int seed);\n// alloc_size/malloc (#649): self-describing sizes for __builtin_object_size,\n// generalizing #642's hardcoded name-based malloc-family detection. realloc\n// and reallocarray are not annotated `malloc` since they may return the same\n// block as their input pointer (not a fresh, non-aliasing allocation).\nextern void* aligned_alloc(size_t alignment, size_t size) __attribute__((alloc_size(2), malloc));\nextern void* calloc(size_t nmemb, size_t size) __attribute__((alloc_size(1, 2), malloc));\nextern void free(void* ptr);\nextern void free_sized(void* ptr, size_t size);\nextern void free_aligned_sized(void* ptr, size_t alignment, size_t size);\nextern void* malloc(size_t size) __attribute__((alloc_size(1), malloc));\nextern void* realloc(void* ptr, size_t size) __attribute__((alloc_size(2)));\n// (#699) Routed through the VM heap's overflow-checked REALCA opcode by\n// default, or the cccc_reallocarray polyfill on the -V/--vm-heap host\n// allocator path -- not a native host FFI call, since not every libc\n// provides reallocarray (e.g. this SDK's macOS does not).\nextern void* reallocarray(void* ptr, size_t nmemb, size_t size) __attribute__((alloc_size(2, 3)));\nextern void abort(void);\nextern int atexit(void (*func)(void));\nextern int at_quick_exit(void (*func)(void));\nextern void exit(int status);\nextern void _Exit(int status);\nextern char* getenv(const char* name);\nextern void quick_exit(int status);\nextern int system(const char* string);\nextern int posix_memalign(void** memptr, size_t alignment, size_t size);\nextern void* bsearch(const void* key, void* base, size_t nmemb, size_t size, int (*compar)(const void* , const void* ));\nextern void qsort(void* base, size_t nmemb, size_t size, int (*compar)(const void* , const void* ));\nextern int abs(int j);\nextern long int labs(long int j);\nextern long long int llabs(long long int j);\n\ntypedef struct { int quot; int rem; } div_t;\ntypedef struct { long quot; long rem; } ldiv_t;\ntypedef struct { long long quot; long long rem; } lldiv_t;\n\nextern div_t div(int numer, int denom);\nextern ldiv_t ldiv(long int numer, long int denom);\nextern lldiv_t lldiv(long long int numer, long long int denom);\n\nextern int mblen(const char* s, size_t n);\nextern int mbtowc(wchar_t* pwc, const char* s, size_t n);\nextern int wctomb(char* s, wchar_t wc);\n\nextern size_t mbstowcs(wchar_t* pwcs, const char* s, size_t n);\nextern size_t wcstombs(char* s, const wchar_t* pwcs, size_t n);\nextern size_t memalignment(const void* p);\n\n#endif\n";
static char __builtin_stdnoreturn_h[85] = "#ifndef __STDNORETURN_H\n#define __STDNORETURN_H\n\n#define noreturn _Noreturn\n\n#endif\n";
static char __builtin_string_h[3000] = "/* string.h - string manipulation functions for CCCC C compiler */\n\n#ifndef __STRING_H\n#define __STRING_H\n\nextern void *memcpy(void *dest, const void *src, long n);\nextern void *memmove(void *dest, const void *src, long n);\nextern void *memset(void *s, int c, long n);\nextern int memcmp(const void *s1, const void *s2, long n);\nextern void *memchr(const void *s, int c, long n);\n\nextern long strlen(const char *s);\nextern char *strcpy(char *dest, const char *src);\nextern char *strncpy(char *dest, const char *src, long n);\nextern char *strcat(char *dest, const char *src);\nextern char *strncat(char *dest, const char *src, long n);\nextern int strcmp(const char *s1, const char *s2);\nextern int strncmp(const char *s1, const char *s2, long n);\n\n/* C23 const-correct search functions: return type matches const-ness of input.\n * Macros use the parenthesized (funcname) form to call the actual function and\n * avoid recursive macro expansion. Declarations use the same form so the macro\n * is never applied to the declaration itself. */\n\n#define strchr(s, c) \\\n    _Generic((s), \\\n        const char *: (const char *)(strchr)((s), (c)), \\\n        char *:                     (strchr)((s), (c)))\nextern char *(strchr)(const char *s, int c);\n\n#define strrchr(s, c) \\\n    _Generic((s), \\\n        const char *: (const char *)(strrchr)((s), (c)), \\\n        char *:                     (strrchr)((s), (c)))\nextern char *(strrchr)(const char *s, int c);\n\n#define strstr(haystack, needle) \\\n    _Generic((haystack), \\\n        const char *: (const char *)(strstr)((haystack), (needle)), \\\n        char *:                     (strstr)((haystack), (needle)))\nextern char *(strstr)(const char *haystack, const char *needle);\n\n#define strpbrk(s, accept) \\\n    _Generic((s), \\\n        const char *: (const char *)(strpbrk)((s), (accept)), \\\n        char *:                     (strpbrk)((s), (accept)))\nextern char *(strpbrk)(const char *s, const char *accept);\n\nextern long strxfrm(char *dest, const char *src, long n);\nextern char* strerror(int errnum);\n\n// extern char* strcpy_s(char *dest, long destsz, const char *src);\n// extern char* strncpy_s(char *dest, long destsz, const char *src, long n);\n// extern char* strcat_s(char *dest, long destsz, const char *src);\n// extern char* strncat_s(char *dest, long destsz, const char *src, long n);\nextern char* strdup(const char *s);\nextern char* strndup(const char *s, long n);\n// extern long strnlen_s(const char *s, long maxsize);\n// extern char* strtok_s(char *str, const char *delim, char **context);\nextern void* memset_explicit(void *s, int c, long n);\n// extern int memset_s(void *s, long smax, int c, long n);\n// extern void* memcpy_s(void *dest, long destsz, const void *src, long n);\n// extern void* memmove_s(void *dest, long destsz, const void *src, long n);\nextern void* memccpy(void *dest, const void *src, int c, long n);\n// extern int strerror_s(char *buf, long bufsz, int errnum);\n// extern long strerrorlen_s(int errnum);\n\n#endif /* __STRING_H */\n";
static char __builtin_strings_h[597] = "/* strings.h - POSIX string functions supplement for CCCC */\n\n#ifndef __STRINGS_H\n#define __STRINGS_H\n\n#ifdef _WIN32\n#error \"<strings.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"stddef.h\"\n\nextern int strcasecmp(const char *s1, const char *s2);\nextern int strncasecmp(const char *s1, const char *s2, size_t n);\nextern void bzero(void *s, size_t n);\nextern void bcopy(const void *src, void *dst, size_t n);\nextern int bcmp(const void *s1, const void *s2, size_t n);\nextern char *index(const char *s, int c);\nextern char *rindex(const char *s, int c);\n\n#endif /* __STRINGS_H */\n";
static char __builtin_sys_cdefs_h[761] = "/*\n * CCCC wrapper for sys/cdefs.h\n * \n * This stub includes Availability.h first (to set up CCCC compatibility macros)\n * then includes the real sys/cdefs.h from the system include path.\n * \n * The order matters because sys/cdefs.h uses __GNUC__ and __has_attribute\n * to define macros that CCCC cannot parse (like __attribute__((__always_inline__))).\n * By including Availability.h first, we ensure __has_attribute returns 0\n * and __attribute__ is stripped.\n */\n\n#ifndef _CCCC_SYS_CDEFS_H_\n#define _CCCC_SYS_CDEFS_H_\n\n/* Include CCCC's Availability.h stub first to set up compatibility macros */\n#include <Availability.h>\n\n/* Now include the real sys/cdefs.h - but we need to use include_next */\n#include_next <sys/cdefs.h>\n\n#endif /* _CCCC_SYS_CDEFS_H_ */\n";
static char __builtin_sys_file_h[459] = "/* sys/file.h - advisory file locking for CCCC */\n\n#ifndef __SYS_FILE_H\n#define __SYS_FILE_H\n\n#ifdef _WIN32\n#error \"<sys/file.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"fcntl.h\"\n\n/* flock() operations */\n#define LOCK_SH 1   /* shared lock */\n#define LOCK_EX 2   /* exclusive lock */\n#define LOCK_NB 4   /* don't block when locking */\n#define LOCK_UN 8   /* unlock */\n\nextern int flock(int fd, int operation);\n\n#endif /* __SYS_FILE_H */\n";
static char __builtin_sys_ioctl_h[698] = "/* sys/ioctl.h - device control operations for CCCC */\n\n#ifndef __SYS_IOCTL_H\n#define __SYS_IOCTL_H\n\n#ifdef _WIN32\n#error \"<sys/ioctl.h> is only available on POSIX targets in CCCC\"\n#endif\n\n/*\n * Terminal window size query (the only ioctl request portable code commonly\n * relies on). The numeric request codes are platform-specific.\n */\n#ifdef __APPLE__\n#define TIOCGWINSZ 0x40087468\n#define TIOCSWINSZ 0x80087467\n#else\n#define TIOCGWINSZ 0x5413\n#define TIOCSWINSZ 0x5414\n#endif\n\nstruct winsize {\n    unsigned short ws_row;\n    unsigned short ws_col;\n    unsigned short ws_xpixel;\n    unsigned short ws_ypixel;\n};\n\nextern int ioctl(int fd, unsigned long request, ...);\n\n#endif /* __SYS_IOCTL_H */\n";
static char __builtin_sys_mman_h[2124] = "/* sys/mman.h - memory management declarations for CCCC */\n\n#ifndef __SYS_MMAN_H\n#define __SYS_MMAN_H\n\n#ifdef _WIN32\n#error \"<sys/mman.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"unistd.h\"\n\n#define PROT_NONE  0x00\n#define PROT_READ  0x01\n#define PROT_WRITE 0x02\n#define PROT_EXEC  0x04\n\n#define MAP_FAILED ((void *)-1)\n\n#ifdef __APPLE__\n#define MAP_SHARED    0x0001\n#define MAP_PRIVATE   0x0002\n#define MAP_FIXED     0x0010\n#define MAP_ANON      0x1000\n#define MAP_ANONYMOUS MAP_ANON\n#else\n#define MAP_SHARED    0x01\n#define MAP_PRIVATE   0x02\n#define MAP_FIXED     0x10\n#define MAP_ANONYMOUS 0x20\n#define MAP_ANON      MAP_ANONYMOUS\n#endif\n\n#define MS_ASYNC      0x0001\n#define MS_SYNC       0x0002\n#define MS_INVALIDATE 0x0004\n\n#define MADV_NORMAL     0\n#define MADV_RANDOM     1\n#define MADV_SEQUENTIAL 2\n#define MADV_WILLNEED   3\n#define MADV_DONTNEED   4\n\n#ifdef __linux__\n#define MREMAP_MAYMOVE 1\n#define MREMAP_FIXED   2\n#endif\n\n/* Memory locking (verified against real macOS and Linux x86_64/aarch64\n   headers -- Linux values match across x86_64/aarch64). */\n#define MCL_CURRENT 1\n#define MCL_FUTURE  2\n#ifdef __linux__\n#define MCL_ONFAULT 4\n#define MAP_LOCKED    0x2000\n#define MAP_POPULATE  0x8000\n#define MAP_NORESERVE 0x4000\n#else\n#define MAP_NORESERVE 0x0040\n#endif\n\nextern void *mmap(void *addr, size_t length, int prot, int flags, int fd, off_t offset);\nextern int munmap(void *addr, size_t length);\nextern int mprotect(void *addr, size_t len, int prot);\nextern int msync(void *addr, size_t len, int flags);\nextern int posix_madvise(void *addr, size_t len, int advice);\nextern int mlock(const void *addr, size_t len);\nextern int munlock(const void *addr, size_t len);\nextern int mlockall(int flags);\nextern int munlockall(void);\nextern int shm_open(const char *name, int oflag, mode_t mode);\nextern int shm_unlink(const char *name);\n#ifdef __linux__\n// mremap resizes/moves an existing mapping; Linux-only glibc/syscall\n// extension, absent on macOS/BSD (#729).\nextern void *mremap(void *old_address, size_t old_size, size_t new_size, int flags, ...);\n#endif\n\n#endif /* __SYS_MMAN_H */\n";
static char __builtin_sys_mount_h[1229] = "/* sys/mount.h - filesystem statistics for CCCC\n *\n * Minimal declarations for statfs()/fstatfs(). The full `struct statfs`\n * layout is highly platform-specific; only the fields portable code commonly\n * reads (block size, flags) are exposed here. Code that needs the complete\n * native layout should query it via the host C library directly.\n */\n\n#ifndef __SYS_MOUNT_H\n#define __SYS_MOUNT_H\n\n#ifdef _WIN32\n#error \"<sys/mount.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"sys/types.h\"\n\n#ifndef MFSTYPENAMELEN\n#define MFSTYPENAMELEN 16\n#endif\n\nstruct statfs {\n    unsigned int  f_bsize;   /* fundamental file system block size */\n    unsigned int  f_iosize;  /* optimal transfer block size */\n    unsigned long f_blocks;  /* total data blocks in file system */\n    unsigned long f_bfree;   /* free blocks in fs */\n    unsigned long f_bavail;  /* free blocks avail to non-superuser */\n    unsigned long f_files;   /* total file nodes in file system */\n    unsigned long f_ffree;   /* free file nodes in fs */\n    unsigned int  f_flags;   /* copy of mount exported flags */\n};\n\nextern int statfs(const char *path, struct statfs *buf);\nextern int fstatfs(int fd, struct statfs *buf);\n\n#endif /* __SYS_MOUNT_H */\n";
static char __builtin_sys_param_h[554] = "/* sys/param.h - system parameters and limits for CCCC */\n\n#ifndef __SYS_PARAM_H\n#define __SYS_PARAM_H\n\n#ifdef _WIN32\n#error \"<sys/param.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"limits.h\"\n\n/* Maximum length of a pathname, including the terminating NUL */\n#ifndef MAXPATHLEN\n#define MAXPATHLEN 1024\n#endif\n\n#ifndef NBBY\n#define NBBY 8   /* number of bits in a byte */\n#endif\n\n#ifndef MIN\n#define MIN(a, b) (((a) < (b)) ? (a) : (b))\n#endif\n#ifndef MAX\n#define MAX(a, b) (((a) > (b)) ? (a) : (b))\n#endif\n\n#endif /* __SYS_PARAM_H */\n";
static char __builtin_sys_resource_h[3701] = "/* sys/resource.h - resource usage declarations for CCCC */\n\n#ifndef __SYS_RESOURCE_H\n#define __SYS_RESOURCE_H\n\n#ifdef _WIN32\n#error \"<sys/resource.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"sys/time.h\"\n\n/* struct rusage (#747), needed by getrusage() and wait3()/wait4(). Layout is\n   identical on macOS and Linux -- verified via sizeof/offsetof against real\n   macOS and Linux x86_64/aarch64 headers (Linux values match across\n   x86_64/aarch64; sizeof(struct rusage) == 144 on both, all fourteen\n   counters after ru_utime/ru_stime are plain `long`). ru_maxrss's *unit*\n   still diverges even though the field's offset/width don't: it is measured\n   in bytes on macOS but kilobytes on Linux -- a real semantic difference,\n   not something this header can paper over. */\nstruct rusage {\n    struct timeval ru_utime;\n    struct timeval ru_stime;\n    long ru_maxrss;\n    long ru_ixrss;\n    long ru_idrss;\n    long ru_isrss;\n    long ru_minflt;\n    long ru_majflt;\n    long ru_nswap;\n    long ru_inblock;\n    long ru_oublock;\n    long ru_msgsnd;\n    long ru_msgrcv;\n    long ru_nsignals;\n    long ru_nvcsw;\n    long ru_nivcsw;\n};\n\n#define RUSAGE_SELF     0\n#define RUSAGE_CHILDREN (-1)\n#ifndef __APPLE__\n/* RUSAGE_THREAD is Linux-only; macOS has no per-thread getrusage(). */\n#define RUSAGE_THREAD   1\n#endif\n\nextern int getrusage(int who, struct rusage *usage);\n\n/* struct rlimit / RLIMIT_* / getrlimit()/setrlimit() (#786). Unlike struct\n   rusage above, the *numbering* of RLIMIT_* genuinely diverges between\n   macOS and Linux (not just extra Linux-only entries) -- verified via\n   sizeof/offsetof/constant probes against real macOS and Linux\n   x86_64/aarch64 headers (Linux values match across x86_64/aarch64;\n   sizeof(struct rlimit) == 16 on both, rlim_cur/rlim_max both plain\n   64-bit rlim_t at offsets 0/8). Notably RLIMIT_AS aliases RLIMIT_RSS on\n   macOS (both 5) but is a distinct value (9) on Linux. RLIM_INFINITY also\n   diverges: macOS uses INT64_MAX-as-unsigned, Linux uses UINT64_MAX. */\ntypedef unsigned long long rlim_t;\n\nstruct rlimit {\n    rlim_t rlim_cur;\n    rlim_t rlim_max;\n};\n\n#ifdef __APPLE__\n#define RLIMIT_CPU     0\n#define RLIMIT_FSIZE   1\n#define RLIMIT_DATA    2\n#define RLIMIT_STACK   3\n#define RLIMIT_CORE    4\n#define RLIMIT_AS      5\n#define RLIMIT_RSS     5\n#define RLIMIT_MEMLOCK 6\n#define RLIMIT_NPROC   7\n#define RLIMIT_NOFILE  8\n#define RLIM_NLIMITS   9\n#define RLIM_INFINITY  ((rlim_t)0x7fffffffffffffffULL)\n#else\n#define RLIMIT_CPU        0\n#define RLIMIT_FSIZE      1\n#define RLIMIT_DATA       2\n#define RLIMIT_STACK      3\n#define RLIMIT_CORE       4\n#define RLIMIT_RSS        5\n#define RLIMIT_NPROC      6\n#define RLIMIT_NOFILE     7\n#define RLIMIT_MEMLOCK    8\n#define RLIMIT_AS         9\n#define RLIMIT_LOCKS      10\n#define RLIMIT_SIGPENDING 11\n#define RLIMIT_MSGQUEUE   12\n#define RLIMIT_NICE       13\n#define RLIMIT_RTPRIO     14\n#define RLIMIT_RTTIME     15\n#define RLIM_NLIMITS      16\n#define RLIM_INFINITY     ((rlim_t)0xffffffffffffffffULL)\n#endif\n#define RLIMIT_NLIMITS RLIM_NLIMITS\n\nextern int getrlimit(int resource, struct rlimit *rlim);\nextern int setrlimit(int resource, const struct rlimit *rlim);\n\n/* getpriority()/setpriority() (#786). PRIO_* values are identical on macOS\n   and Linux -- verified against real headers. getpriority() legitimately\n   returns -1 on success (a valid nice value), so callers must clear errno\n   before the call and check it afterward rather than testing the return\n   value alone. */\n#define PRIO_PROCESS 0\n#define PRIO_PGRP    1\n#define PRIO_USER    2\n\nextern int getpriority(int which, int who);\nextern int setpriority(int which, int who, int prio);\n\n#endif /* __SYS_RESOURCE_H */\n";
static char __builtin_sys_select_h[1699] = "/* sys/select.h - synchronous I/O multiplexing for CCCC\n *\n * sizeof(fd_set) == 128 and FD_SETSIZE == 1024 on both macOS and Linux\n * (verified via probe). The underlying word width used to address bits\n * differs (4 bytes on macOS's `int32_t fds_bits[32]`, 8 bytes on Linux's\n * `long fds_bits[16]`), but both are little-endian on every arch CCCC\n * supports, so bit k always lands at byte k/8, bit k%8 regardless of word\n * width -- fd_set is declared here as a flat byte array and FD_SET/FD_CLR/\n * FD_ISSET operate byte-wise, sidestepping the word-width divergence\n * entirely rather than needing a per-platform layout.\n */\n\n#ifndef __SYS_SELECT_H\n#define __SYS_SELECT_H\n\n#ifdef _WIN32\n#error \"<sys/select.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"sys/time.h\"\n#include \"signal.h\"\n\n#define FD_SETSIZE 1024\n\ntypedef struct {\n    unsigned char __fds_bits[FD_SETSIZE / 8];\n} fd_set;\n\n#define FD_ZERO(set) \\\n    do { \\\n        for (unsigned __i = 0; __i < sizeof((set)->__fds_bits); __i++) \\\n            (set)->__fds_bits[__i] = 0; \\\n    } while (0)\n\n#define FD_SET(fd, set)   ((set)->__fds_bits[(fd) / 8] |=  (unsigned char)(1u << ((fd) % 8)))\n#define FD_CLR(fd, set)   ((set)->__fds_bits[(fd) / 8] &= (unsigned char)~(1u << ((fd) % 8)))\n#define FD_ISSET(fd, set) (((set)->__fds_bits[(fd) / 8] & (unsigned char)(1u << ((fd) % 8))) != 0)\n\nextern int select(int nfds, fd_set *readfds, fd_set *writefds,\n                   fd_set *exceptfds, struct timeval *timeout);\nextern int pselect(int nfds, fd_set *readfds, fd_set *writefds,\n                    fd_set *exceptfds, const struct timespec *timeout,\n                    const sigset_t *sigmask);\n\n#endif /* __SYS_SELECT_H */\n";
static char __builtin_sys_socket_h[6702] = "/* sys/socket.h - socket declarations for CCCC */\n\n#ifndef __SYS_SOCKET_H\n#define __SYS_SOCKET_H\n\n#ifdef _WIN32\n#error \"<sys/socket.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"sys/types.h\"\n#include \"unistd.h\" /* for ssize_t */\n\n#ifdef __APPLE__\nstruct sockaddr {\n    unsigned char sa_len;\n    sa_family_t sa_family;\n    char sa_data[14];\n};\n#else\nstruct sockaddr {\n    sa_family_t sa_family;\n    char sa_data[14];\n};\n#endif\n\n#define SOCK_STREAM 1\n#define SOCK_DGRAM  2\n#define SOCK_RAW    3\n\n#define AF_UNIX  1\n#define AF_LOCAL AF_UNIX\n#define PF_UNIX  AF_UNIX\n#define PF_LOCAL AF_LOCAL\n\n#ifdef __linux__\n/* macOS has no equivalent type-OR'd-into-socket()'s-type-argument flags for\n   these; they're a Linux-only extension (SOCK_STREAM|SOCK_CLOEXEC etc). */\n#define SOCK_CLOEXEC  0x80000\n#define SOCK_NONBLOCK 0x800\n#endif\n\n#ifdef __APPLE__\n#define SOL_SOCKET   0xffff\n#define SO_DEBUG     0x0001\n#define SO_ACCEPTCONN 0x0002\n#define SO_REUSEADDR 0x0004\n#define SO_KEEPALIVE 0x0008\n#define SO_DONTROUTE 0x0010\n#define SO_BROADCAST 0x0020\n#define SO_LINGER    0x0080\n#define SO_OOBINLINE 0x0100\n#define SO_REUSEPORT 0x0200\n#define SO_SNDBUF    0x1001\n#define SO_RCVBUF    0x1002\n#define SO_SNDTIMEO  0x1005\n#define SO_RCVTIMEO  0x1006\n#define SO_ERROR     0x1007\n#define SO_TYPE      0x1008\n/* SO_NOSIGPIPE (setsockopt-level, suppresses SIGPIPE for the socket's\n   lifetime) predates MSG_NOSIGNAL on macOS and is the idiomatic way to get\n   this behavior, but modern macOS SDKs (verified: MacOSX14/14.5/15/15.5)\n   also define MSG_NOSIGNAL as a real per-call send() flag, so both are\n   provided rather than only the historical one. */\n#define SO_NOSIGPIPE 0x1022\n#else\n#define SOL_SOCKET   1\n#define SO_DEBUG     1\n#define SO_REUSEADDR 2\n#define SO_TYPE      3\n#define SO_ERROR     4\n#define SO_DONTROUTE 5\n#define SO_BROADCAST 6\n#define SO_SNDBUF    7\n#define SO_RCVBUF    8\n#define SO_KEEPALIVE 9\n#define SO_OOBINLINE 10\n#define SO_LINGER    13\n#define SO_REUSEPORT 15\n#define SO_RCVTIMEO  20\n#define SO_SNDTIMEO  21\n#define SO_ACCEPTCONN 30\n#endif\n\n#define SHUT_RD   0\n#define SHUT_WR   1\n#define SHUT_RDWR 2\n\n/* struct msghdr / struct cmsghdr for sendmsg()/recvmsg() ancillary\n   (control) data (#741). msg_iovlen/msg_controllen and cmsg_len are\n   socklen_t/int (4 bytes) on macOS vs size_t (8 bytes) on Linux --\n   verified via offsetof/sizeof against real macOS and Linux\n   x86_64/aarch64 headers (Linux values match across x86_64/aarch64).\n   struct iovec comes from sys/uio.h, transitively included via\n   unistd.h above (#792). */\n#ifdef __APPLE__\nstruct msghdr {\n    void         *msg_name;\n    socklen_t     msg_namelen;\n    struct iovec *msg_iov;\n    int           msg_iovlen;\n    void         *msg_control;\n    socklen_t     msg_controllen;\n    int           msg_flags;\n};\n\nstruct cmsghdr {\n    socklen_t cmsg_len;\n    int       cmsg_level;\n    int       cmsg_type;\n};\n#else\nstruct msghdr {\n    void         *msg_name;\n    socklen_t     msg_namelen;\n    struct iovec *msg_iov;\n    size_t        msg_iovlen;\n    void         *msg_control;\n    size_t        msg_controllen;\n    int           msg_flags;\n};\n\nstruct cmsghdr {\n    size_t cmsg_len;\n    int    cmsg_level;\n    int    cmsg_type;\n};\n#endif\n\n#define SCM_RIGHTS 1\n\n/* CMSG_ALIGN rounds to the width of cmsg_len -- 4 bytes (sizeof(int)) on\n   macOS (__DARWIN_ALIGN32), 8 bytes (sizeof(size_t)) on 64-bit Linux.\n   This is our own definition, not the host's private macro -- verified\n   sizeof(struct cmsghdr) == 12 (macOS) / 16 (Linux) so CMSG_SPACE/CMSG_LEN\n   land on the same byte offsets as the host ABI. */\n#ifdef __APPLE__\n#define __CCCC_CMSG_ALIGN(n) (((size_t)(n) + sizeof(int) - 1) & ~(sizeof(int) - 1))\n#else\n#define __CCCC_CMSG_ALIGN(n) (((size_t)(n) + sizeof(size_t) - 1) & ~(sizeof(size_t) - 1))\n#endif\n\n#define CMSG_ALIGN(n)   __CCCC_CMSG_ALIGN(n)\n#define CMSG_SPACE(len) (__CCCC_CMSG_ALIGN(sizeof(struct cmsghdr)) + __CCCC_CMSG_ALIGN(len))\n#define CMSG_LEN(len)   (__CCCC_CMSG_ALIGN(sizeof(struct cmsghdr)) + (len))\n#define CMSG_FIRSTHDR(mhdr) \\\n    ((size_t)(mhdr)->msg_controllen >= sizeof(struct cmsghdr) ? \\\n     (struct cmsghdr *)(mhdr)->msg_control : (struct cmsghdr *)0)\n#define CMSG_DATA(cmsg) ((unsigned char *)(cmsg) + __CCCC_CMSG_ALIGN(sizeof(struct cmsghdr)))\n#define CMSG_NXTHDR(mhdr, cmsg) \\\n    (((unsigned char *)(cmsg) + __CCCC_CMSG_ALIGN((cmsg)->cmsg_len) + sizeof(struct cmsghdr) > \\\n      (unsigned char *)(mhdr)->msg_control + (mhdr)->msg_controllen) ? \\\n     (struct cmsghdr *)0 : \\\n     (struct cmsghdr *)((unsigned char *)(cmsg) + __CCCC_CMSG_ALIGN((cmsg)->cmsg_len)))\n\n#ifdef __APPLE__\n#define MSG_OOB       0x1\n#define MSG_PEEK      0x2\n#define MSG_DONTROUTE 0x4\n#define MSG_EOR       0x8\n#define MSG_TRUNC     0x10\n#define MSG_CTRUNC    0x20\n#define MSG_WAITALL   0x40\n#define MSG_DONTWAIT  0x80\n#define MSG_NOSIGNAL  0x80000\n#else\n#define MSG_OOB       0x1\n#define MSG_PEEK      0x2\n#define MSG_DONTROUTE 0x4\n#define MSG_CTRUNC    0x8\n#define MSG_TRUNC     0x20\n#define MSG_DONTWAIT  0x40\n#define MSG_EOR       0x80\n#define MSG_WAITALL   0x100\n#define MSG_NOSIGNAL  0x4000\n#endif\n\nextern int socket(int domain, int type, int protocol);\nextern int socketpair(int domain, int type, int protocol, int sv[2]);\nextern int bind(int socket, const struct sockaddr *address, socklen_t address_len);\nextern int listen(int socket, int backlog);\nextern int accept(int socket, struct sockaddr *address, socklen_t *address_len);\nextern int connect(int socket, const struct sockaddr *address, socklen_t address_len);\nextern int setsockopt(int socket, int level, int option_name,\n                      const void *option_value, socklen_t option_len);\nextern int getsockopt(int socket, int level, int option_name,\n                      void *option_value, socklen_t *option_len);\nextern int getsockname(int socket, struct sockaddr *address, socklen_t *address_len);\nextern int getpeername(int socket, struct sockaddr *address, socklen_t *address_len);\nextern int shutdown(int socket, int how);\n\n/* Data transfer */\nextern ssize_t recv(int socket, void *buffer, size_t length, int flags);\nextern ssize_t send(int socket, const void *buffer, size_t length, int flags);\nextern ssize_t recvfrom(int socket, void *buffer, size_t length, int flags,\n                        struct sockaddr *address, socklen_t *address_len);\nextern ssize_t sendto(int socket, const void *message, size_t length, int flags,\n                      const struct sockaddr *dest_addr, socklen_t dest_len);\nextern ssize_t sendmsg(int socket, const struct msghdr *message, int flags);\nextern ssize_t recvmsg(int socket, struct msghdr *message, int flags);\nextern int sockatmark(int fd);\n\n#endif /* __SYS_SOCKET_H */\n";
static char __builtin_sys_stat_h[3974] = "/* sys/stat.h - file status for CCCC */\n\n#ifndef __SYS_STAT_H\n#define __SYS_STAT_H\n\n#ifdef _WIN32\n#error \"<sys/stat.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"sys/types.h\"\n\n/* Pull in struct timespec and time_t */\n#include \"../time.h\"\n\n#ifdef __APPLE__\n\nstruct stat {\n    dev_t     st_dev;\n    mode_t    st_mode;\n    nlink_t   st_nlink;\n    ino_t     st_ino;\n    uid_t     st_uid;\n    gid_t     st_gid;\n    dev_t     st_rdev;\n    struct timespec st_atimespec;\n    struct timespec st_mtimespec;\n    struct timespec st_ctimespec;\n    struct timespec st_birthtimespec;\n    off_t     st_size;\n    blkcnt_t  st_blocks;\n    blksize_t st_blksize;\n    unsigned int st_flags;\n    unsigned int st_gen;\n    int       st_lspare;\n    long long st_qspare[2];\n};\n\n#elif defined(__x86_64__)\n/* Linux x86_64 glibc layout (sizeof==144, offsetof(st_size)==48, offsetof(st_mtim)==88) */\n\nstruct stat {\n    dev_t     st_dev;\n    ino_t     st_ino;\n    nlink_t   st_nlink;   /* nlink precedes mode on x86_64 */\n    mode_t    st_mode;\n    uid_t     st_uid;\n    gid_t     st_gid;\n    int       __pad0;\n    dev_t     st_rdev;\n    off_t     st_size;\n    blksize_t st_blksize; /* long (8 bytes) on x86_64 */\n    blkcnt_t  st_blocks;\n    struct timespec st_atim;\n    struct timespec st_mtim;\n    struct timespec st_ctim;\n    long      __glibc_reserved[3];\n};\n\n_Static_assert(sizeof(struct stat) == 144, \"x86_64 struct stat layout mismatch\");\n\n#else\n/* Linux aarch64 / generic POSIX */\n\nstruct stat {\n    dev_t st_dev;\n    ino_t st_ino;\n    mode_t st_mode;\n    nlink_t st_nlink;\n    uid_t st_uid;\n    gid_t st_gid;\n    dev_t st_rdev;\n    dev_t __pad1;\n    off_t st_size;\n    blksize_t st_blksize;\n    int __pad2;\n    blkcnt_t st_blocks;\n    struct timespec st_atim;\n    struct timespec st_mtim;\n    struct timespec st_ctim;\n    int __glibc_reserved[2];\n};\n\n#endif\n\n#define S_IFMT   0xF000\n#define S_IFIFO  0x1000\n#define S_IFCHR  0x2000\n#define S_IFDIR  0x4000\n#define S_IFBLK  0x6000\n#define S_IFREG  0x8000\n#define S_IFLNK  0xA000\n#define S_IFSOCK 0xC000\n\n#define S_ISFIFO(m) (((m) & S_IFMT) == S_IFIFO)\n#define S_ISCHR(m)  (((m) & S_IFMT) == S_IFCHR)\n#define S_ISDIR(m)  (((m) & S_IFMT) == S_IFDIR)\n#define S_ISBLK(m)  (((m) & S_IFMT) == S_IFBLK)\n#define S_ISREG(m)  (((m) & S_IFMT) == S_IFREG)\n#define S_ISLNK(m)  (((m) & S_IFMT) == S_IFLNK)\n#define S_ISSOCK(m) (((m) & S_IFMT) == S_IFSOCK)\n\n#define S_IRWXU  0700\n#define S_IRUSR  0400\n#define S_IWUSR  0200\n#define S_IXUSR  0100\n#define S_IRWXG  0070\n#define S_IRGRP  0040\n#define S_IWGRP  0020\n#define S_IXGRP  0010\n#define S_IRWXO  0007\n#define S_IROTH  0004\n#define S_IWOTH  0002\n#define S_IXOTH  0001\n\n#define S_ISUID  04000\n#define S_ISGID  02000\n#define S_ISVTX  01000\n\n/* Sentinel tv_nsec values for utimensat()/futimens() */\n#ifdef __APPLE__\n#define UTIME_NOW  -1\n#define UTIME_OMIT -2\n#else\n#define UTIME_NOW  0x3FFFFFFF\n#define UTIME_OMIT 0x3FFFFFFE\n#endif\n\n/* *at() family: fd + flag constants (verified against real macOS and Linux\n   x86_64/aarch64 headers -- Linux x86_64/aarch64 values match each other). */\n#ifdef __APPLE__\n#define AT_FDCWD             -2\n#define AT_SYMLINK_NOFOLLOW  0x0020\n#define AT_REMOVEDIR         0x0080\n#else\n#define AT_FDCWD             -100\n#define AT_SYMLINK_NOFOLLOW  0x100\n#define AT_REMOVEDIR         0x200\n#endif\n\nextern int stat(const char *path, struct stat *buf);\nextern int fstat(int fd, struct stat *buf);\nextern int lstat(const char *path, struct stat *buf);\nextern int fstatat(int fd, const char *path, struct stat *buf, int flag);\nextern int chmod(const char *path, mode_t mode);\nextern int fchmod(int fd, mode_t mode);\nextern int fchmodat(int fd, const char *path, mode_t mode, int flag);\nextern int mkdir(const char *path, mode_t mode);\nextern int mkdirat(int fd, const char *path, mode_t mode);\nextern int mkfifo(const char *path, mode_t mode);\nextern int mknod(const char *path, mode_t mode, dev_t dev);\nextern mode_t umask(mode_t cmask);\n\n#endif /* __SYS_STAT_H */\n";
static char __builtin_sys_statvfs_h[1464] = "/* sys/statvfs.h - filesystem statistics (POSIX) for CCCC\n *\n * struct statvfs diverges hard between the two supported hosts: 64 bytes with\n * 32-bit counters on macOS vs 112 bytes with 64-bit counters on Linux (verified\n * against real headers/probe). Rather than expose either host layout directly,\n * this declares a CCCC-canonical struct in POSIX field order with wide\n * (unsigned long) counters on both platforms; wrap_statvfs/wrap_fstatvfs\n * (src/stdlib/posix.c) populate a host-local struct via the real statvfs()/\n * fstatvfs() and copy field-by-field, the same shape as wrap_statfs (see\n * sys/mount.h) uses for the non-standard struct statfs.\n */\n\n#ifndef __SYS_STATVFS_H\n#define __SYS_STATVFS_H\n\n#ifdef _WIN32\n#error \"<sys/statvfs.h> is only available on POSIX targets in CCCC\"\n#endif\n\nstruct statvfs {\n    unsigned long f_bsize;\n    unsigned long f_frsize;\n    unsigned long f_blocks;\n    unsigned long f_bfree;\n    unsigned long f_bavail;\n    unsigned long f_files;\n    unsigned long f_ffree;\n    unsigned long f_favail;\n    unsigned long f_fsid;\n    unsigned long f_flag;\n    unsigned long f_namemax;\n};\n\n/* f_flag bits -- identical numbering on macOS and Linux. */\n#define ST_RDONLY 1\n#define ST_NOSUID 2\n\n#ifdef __linux__\n#define ST_NODEV       4\n#define ST_NOEXEC      8\n#define ST_SYNCHRONOUS 16\n#endif\n\nextern int statvfs(const char *path, struct statvfs *buf);\nextern int fstatvfs(int fd, struct statvfs *buf);\n\n#endif /* __SYS_STATVFS_H */\n";
static char __builtin_sys_time_h[2286] = "/* sys/time.h - time types for CCCC */\n\n#ifndef __SYS_TIME_H\n#define __SYS_TIME_H\n\n#ifdef _WIN32\n#error \"<sys/time.h> is only available on POSIX targets in CCCC\"\n#endif\n\n/* Quoted includes resolve relative to the including header's own directory\n   first; a bare \"time.h\" from within include/sys/ joins to \"sys/time.h\" --\n   this file itself -- and silently no-ops (include-guard self-reference)\n   instead of reaching the real top-level time.h. Use \"../time.h\" like\n   sys/times.h already does. */\n#include \"../time.h\"\n\n/* tv_usec is `__darwin_suseconds_t` (a 4-byte int32) on macOS but a plain\n   8-byte `long` on Linux -- sizeof(struct timeval) == 16 on both, but a\n   guest-side `long tv_usec` (8 bytes) previously meant the host only wrote\n   the low 4 bytes on macOS, leaving the upper 4 bytes as stale garbage\n   after gettimeofday()/getitimer()/etc. (found probing for #798). */\nstruct timeval {\n    long tv_sec;\n#ifdef __APPLE__\n    int tv_usec;\n    int __cccc_tv_usec_pad;\n#else\n    long tv_usec;\n#endif\n};\n\nstruct timezone {\n    int tz_minuteswest;\n    int tz_dsttime;\n};\n\nextern int gettimeofday(struct timeval *tv, struct timezone *tz);\nextern int settimeofday(const struct timeval *tv, const struct timezone *tz);\nextern int utimes(const char *path, const struct timeval times[2]);\nextern int futimes(int fd, const struct timeval times[2]);\nextern int lutimes(const char *path, const struct timeval times[2]);\n\nstruct itimerval {\n    struct timeval it_interval;\n    struct timeval it_value;\n};\n\n#define ITIMER_REAL    0\n#define ITIMER_VIRTUAL 1\n#define ITIMER_PROF    2\n\nextern int setitimer(int which, const struct itimerval *new_value, struct itimerval *old_value);\nextern int getitimer(int which, struct itimerval *curr_value);\n\n#define timeradd(a, b, res) do { \\\n    (res)->tv_sec = (a)->tv_sec + (b)->tv_sec; \\\n    (res)->tv_usec = (a)->tv_usec + (b)->tv_usec; \\\n    if ((res)->tv_usec >= 1000000) { \\\n        (res)->tv_sec++; \\\n        (res)->tv_usec -= 1000000; \\\n    } \\\n} while (0)\n\n#define timersub(a, b, res) do { \\\n    (res)->tv_sec = (a)->tv_sec - (b)->tv_sec; \\\n    (res)->tv_usec = (a)->tv_usec - (b)->tv_usec; \\\n    if ((res)->tv_usec < 0) { \\\n        (res)->tv_sec--; \\\n        (res)->tv_usec += 1000000; \\\n    } \\\n} while (0)\n\n#endif /* __SYS_TIME_H */\n";
static char __builtin_sys_times_h[708] = "/* sys/times.h - process times declarations for CCCC */\n\n#ifndef __SYS_TIMES_H\n#define __SYS_TIMES_H\n\n#ifdef _WIN32\n#error \"<sys/times.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"../time.h\" /* for clock_t */\n\n/* struct tms (#733/#737). Layout is identical on macOS and Linux -- verified\n   via sizeof/offsetof against real macOS and Linux x86_64/aarch64 headers\n   (Linux values match across x86_64/aarch64): sizeof(struct tms) == 32 on\n   both, all four fields plain 8-byte clock_t at offsets 0/8/16/24. */\nstruct tms {\n    clock_t tms_utime;\n    clock_t tms_stime;\n    clock_t tms_cutime;\n    clock_t tms_cstime;\n};\n\nextern clock_t times(struct tms *buf);\n\n#endif /* __SYS_TIMES_H */\n";
static char __builtin_sys_types_h[1947] = "/* sys/types.h - basic system types for CCCC */\n\n#ifndef __SYS_TYPES_H\n#define __SYS_TYPES_H\n\n#ifdef _WIN32\n#error \"<sys/types.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#ifdef __APPLE__\ntypedef int               dev_t;\ntypedef unsigned long long ino_t;\ntypedef unsigned short    mode_t;\ntypedef unsigned short    nlink_t;\ntypedef unsigned int      uid_t;\ntypedef unsigned int      gid_t;\ntypedef long long         off_t;\ntypedef int               pid_t;\ntypedef int               blksize_t;\ntypedef long long         blkcnt_t;\ntypedef unsigned int      useconds_t;\ntypedef unsigned char     sa_family_t;\ntypedef unsigned int      socklen_t;\ntypedef int               clockid_t;\ntypedef int                key_t;\ntypedef unsigned int       id_t;\ntypedef unsigned int       fsblkcnt_t;\ntypedef unsigned int       fsfilcnt_t;\ntypedef int                nl_item;\n/* timer_t (POSIX timer_create/timer_settime API) intentionally omitted:\n   macOS does not implement this API, so there is no host type to alias. */\n#else\n/* Linux / generic POSIX */\ntypedef unsigned long     dev_t;\ntypedef unsigned long     ino_t;\ntypedef unsigned int      mode_t;\n#if defined(__aarch64__)\ntypedef unsigned int      nlink_t;\n#else\ntypedef unsigned long     nlink_t;\n#endif\ntypedef unsigned int      uid_t;\ntypedef unsigned int      gid_t;\ntypedef long              off_t;\ntypedef int               pid_t;\n#if defined(__aarch64__)\ntypedef int               blksize_t;\n#else\ntypedef long              blksize_t;\n#endif\ntypedef long              blkcnt_t;\ntypedef unsigned int      useconds_t;\ntypedef unsigned short    sa_family_t;\ntypedef unsigned int      socklen_t;\ntypedef int               clockid_t;\ntypedef void              *timer_t;\ntypedef int                key_t;\ntypedef unsigned int       id_t;\ntypedef unsigned long      fsblkcnt_t;\ntypedef unsigned long      fsfilcnt_t;\ntypedef int                nl_item;\n#endif\n\n#endif /* __SYS_TYPES_H */\n";
static char __builtin_sys_uio_h[493] = "/* sys/uio.h - scatter/gather I/O declarations for CCCC */\n\n#ifndef __SYS_UIO_H\n#define __SYS_UIO_H\n\n#ifdef _WIN32\n#error \"<sys/uio.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"stddef.h\"\n\n#ifndef _SSIZE_T\ntypedef long ssize_t;\n#define _SSIZE_T\n#endif\n\nstruct iovec {\n    void *iov_base;\n    size_t iov_len;\n};\n\nextern ssize_t readv(int fd, const struct iovec *iov, int iovcnt);\nextern ssize_t writev(int fd, const struct iovec *iov, int iovcnt);\n\n#endif /* __SYS_UIO_H */\n";
static char __builtin_sys_un_h[474] = "/* sys/un.h - Unix domain socket address declarations for CCCC */\n\n#ifndef __SYS_UN_H\n#define __SYS_UN_H\n\n#ifdef _WIN32\n#error \"<sys/un.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"sys/types.h\"\n#include \"sys/socket.h\"\n\n#ifdef __APPLE__\nstruct sockaddr_un {\n    unsigned char sun_len;\n    sa_family_t sun_family;\n    char sun_path[104];\n};\n#else\nstruct sockaddr_un {\n    sa_family_t sun_family;\n    char sun_path[108];\n};\n#endif\n\n#endif /* __SYS_UN_H */\n";
static char __builtin_sys_utsname_h[1418] = "/* sys/utsname.h - system identification declarations for CCCC */\n\n#ifndef __SYS_UTSNAME_H\n#define __SYS_UTSNAME_H\n\n#ifdef _WIN32\n#error \"<sys/utsname.h> is only available on POSIX targets in CCCC\"\n#endif\n\n/* struct utsname (#733/#737). Field count/order is identical on macOS and\n   Linux (sysname/nodename/release/version/machine, POSIX-mandated order),\n   but the per-field length diverges -- verified via sizeof/offsetof against\n   real macOS and Linux x86_64/aarch64 headers: each field is a 256-byte\n   char array on macOS (sizeof(struct utsname) == 1280) vs a 65-byte char\n   array on Linux (sizeof(struct utsname) == 390, Linux values match across\n   x86_64/aarch64). Linux also appends a glibc-only `domainname` field\n   (NIS/YP domain name, offset 325) that macOS has no equivalent of at all. */\n#ifdef __APPLE__\n#define _CCCC_UTSNAME_LEN 256\nstruct utsname {\n    char sysname[_CCCC_UTSNAME_LEN];\n    char nodename[_CCCC_UTSNAME_LEN];\n    char release[_CCCC_UTSNAME_LEN];\n    char version[_CCCC_UTSNAME_LEN];\n    char machine[_CCCC_UTSNAME_LEN];\n};\n#else\n#define _CCCC_UTSNAME_LEN 65\nstruct utsname {\n    char sysname[_CCCC_UTSNAME_LEN];\n    char nodename[_CCCC_UTSNAME_LEN];\n    char release[_CCCC_UTSNAME_LEN];\n    char version[_CCCC_UTSNAME_LEN];\n    char machine[_CCCC_UTSNAME_LEN];\n    char domainname[_CCCC_UTSNAME_LEN];\n};\n#endif\n\nextern int uname(struct utsname *buf);\n\n#endif /* __SYS_UTSNAME_H */\n";
static char __builtin_sys_wait_h[2018] = "/* sys/wait.h - process wait declarations for CCCC */\n\n#ifndef __SYS_WAIT_H\n#define __SYS_WAIT_H\n\n#ifdef _WIN32\n#error \"<sys/wait.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"signal.h\" /* for siginfo_t, waitid()'s 3rd argument */\n#include \"sys/resource.h\" /* for struct rusage, wait3()/wait4()'s last argument */\n#include \"unistd.h\"\n\n#define WNOHANG    1\n#define WUNTRACED  2\n\n#define WIFEXITED(status)   (((status) & 0x7f) == 0)\n#define WEXITSTATUS(status) (((status) >> 8) & 0xff)\n#define WIFSIGNALED(status) ((((status) & 0x7f) > 0) && (((status) & 0x7f) < 0x7f))\n#define WTERMSIG(status)    ((status) & 0x7f)\n#define WIFSTOPPED(status)  (((status) & 0xff) == 0x7f)\n#define WSTOPSIG(status)    WEXITSTATUS(status)\n#define WCOREDUMP(status)   ((status) & 0x80)\n\n#ifdef __APPLE__\n#define WCONTINUED 0x10\n#define WIFCONTINUED(status) (WSTOPSIG(status) == 0x13)\n/* waitid() 4th-argument flags (verified against real macOS header). */\n#define WEXITED  0x00000004\n#define WSTOPPED 0x00000008\n#define WNOWAIT  0x00000020\n#else\n#define WCONTINUED 8\n#define WIFCONTINUED(status) ((status) == 0xffff)\n/* waitid() 4th-argument flags (verified against real Linux x86_64/aarch64\n   headers -- values match across x86_64/aarch64). */\n#define WSTOPPED 2\n#define WEXITED  4\n#define WNOWAIT  0x01000000\n#endif\n\nextern pid_t wait(int *status);\nextern pid_t waitpid(pid_t pid, int *status, int options);\n\n/* waitid() (#744). idtype_t/P_* values are identical on macOS and Linux\n   (verified against real headers on both). */\ntypedef enum {\n    P_ALL  = 0,\n    P_PID  = 1,\n    P_PGID = 2\n} idtype_t;\n\nextern int waitid(idtype_t idtype, id_t id, siginfo_t *infop, int options);\n\n/* wait3()/wait4() (#747) -- BSD-style wait variants that also fill a\n   struct rusage for the reaped child. Signatures are identical on macOS\n   and Linux. */\nextern pid_t wait3(int *status, int options, struct rusage *rusage);\nextern pid_t wait4(pid_t pid, int *status, int options, struct rusage *rusage);\n\n#endif /* __SYS_WAIT_H */\n";
static char __builtin_syslog_h[1944] = "/* syslog.h - system logger interface for CCCC\n *\n * All LOG_* priority, option, and facility values are identical on macOS\n * and glibc/Linux (verified via probe on macOS arm64 and Linux x86_64/\n * aarch64) -- unguarded constants, #803.\n */\n\n#ifndef __SYSLOG_H\n#define __SYSLOG_H\n\n#ifdef _WIN32\n#error \"<syslog.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"stdarg.h\"\n\n/* Priorities */\n#define LOG_EMERG   0\n#define LOG_ALERT   1\n#define LOG_CRIT    2\n#define LOG_ERR     3\n#define LOG_WARNING 4\n#define LOG_NOTICE  5\n#define LOG_INFO    6\n#define LOG_DEBUG   7\n\n#define LOG_PRIMASK 0x07\n#define LOG_PRI(p)  ((p) & LOG_PRIMASK)\n#define LOG_MAKEPRI(fac, pri) ((fac) | (pri))\n\n/* Facilities */\n#define LOG_KERN     (0  << 3)\n#define LOG_USER     (1  << 3)\n#define LOG_MAIL     (2  << 3)\n#define LOG_DAEMON   (3  << 3)\n#define LOG_AUTH     (4  << 3)\n#define LOG_SYSLOG   (5  << 3)\n#define LOG_LPR      (6  << 3)\n#define LOG_NEWS     (7  << 3)\n#define LOG_UUCP     (8  << 3)\n#define LOG_CRON     (9  << 3)\n#define LOG_AUTHPRIV (10 << 3)\n#define LOG_FTP      (11 << 3)\n#define LOG_LOCAL0   (16 << 3)\n#define LOG_LOCAL1   (17 << 3)\n#define LOG_LOCAL2   (18 << 3)\n#define LOG_LOCAL3   (19 << 3)\n#define LOG_LOCAL4   (20 << 3)\n#define LOG_LOCAL5   (21 << 3)\n#define LOG_LOCAL6   (22 << 3)\n#define LOG_LOCAL7   (23 << 3)\n\n#define LOG_FACMASK  0x03f8\n#define LOG_FAC(p)   (((p) & LOG_FACMASK) >> 3)\n\n#define LOG_MASK(pri)   (1 << (pri))\n#define LOG_UPTO(pri)   ((1 << ((pri) + 1)) - 1)\n\n/* openlog() options */\n#define LOG_PID    0x01\n#define LOG_CONS   0x02\n#define LOG_ODELAY 0x04\n#define LOG_NDELAY 0x08\n#define LOG_NOWAIT 0x10\n#define LOG_PERROR 0x20\n\nextern void openlog(const char *ident, int option, int facility);\nextern void closelog(void);\nextern void syslog(int priority, const char *format, ...);\nextern void vsyslog(int priority, const char *format, va_list ap);\nextern int setlogmask(int mask);\n\n#endif /* __SYSLOG_H */\n";
static char __builtin_tar_h[1093] = "/* tar.h - extended tar archive format constants for CCCC */\n\n#ifndef __TAR_H\n#define __TAR_H\n\n/* Values are fixed by POSIX.1 itself, not by any host libc -- identical on\n   every platform, nothing to verify. Header-only, no wrapper functions. */\n\n#define TSUID   04000\n#define TSGID   02000\n#define TSVTX   01000\n#define TUREAD  00400\n#define TUWRITE 00200\n#define TUEXEC  00100\n#define TGREAD  00040\n#define TGWRITE 00020\n#define TGEXEC  00010\n#define TOREAD  00004\n#define TOWRITE 00002\n#define TOEXEC  00001\n\n#define REGTYPE   '0' /* Regular file (preferred code). */\n#define AREGTYPE  '\\0' /* Regular file (alternate code). */\n#define LNKTYPE   '1' /* Hard link. */\n#define SYMTYPE   '2' /* Symbolic link (hard if not supported). */\n#define CHRTYPE   '3' /* Character special. */\n#define BLKTYPE   '4' /* Block special. */\n#define DIRTYPE   '5' /* Directory. */\n#define FIFOTYPE  '6' /* Named pipe. */\n#define CONTTYPE  '7' /* Contiguous file (regular file if not supported). */\n\n#define TMAGIC   \"ustar\"\n#define TMAGLEN  6\n#define TVERSION \"00\"\n#define TVERSLEN 2\n\n#endif /* __TAR_H */\n";
static char __builtin_termios_h[5016] = "/* termios.h - terminal I/O declarations for CCCC */\n\n#ifndef __TERMIOS_H\n#define __TERMIOS_H\n\n#ifdef _WIN32\n#error \"<termios.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#ifdef __APPLE__\ntypedef unsigned long tcflag_t;\ntypedef unsigned char cc_t;\ntypedef unsigned long speed_t;\n#define NCCS 20\nstruct termios {\n    tcflag_t c_iflag;\n    tcflag_t c_oflag;\n    tcflag_t c_cflag;\n    tcflag_t c_lflag;\n    cc_t c_cc[NCCS];\n    speed_t c_ispeed;\n    speed_t c_ospeed;\n};\n#else\ntypedef unsigned int tcflag_t;\ntypedef unsigned char cc_t;\ntypedef unsigned int speed_t;\n#define NCCS 32\nstruct termios {\n    tcflag_t c_iflag;\n    tcflag_t c_oflag;\n    tcflag_t c_cflag;\n    tcflag_t c_lflag;\n    cc_t c_line;\n    cc_t c_cc[NCCS];\n    speed_t c_ispeed;\n    speed_t c_ospeed;\n};\n#endif\n\n#define TCSANOW   0\n#define TCSADRAIN 1\n#define TCSAFLUSH 2\n\n/* c_iflag/c_oflag/c_cflag/c_lflag bits and c_cc[] indices differ between\n   macOS/BSD (<sys/termios.h>) and Linux (<asm-generic/termbits.h> via glibc\n   <bits/termios.h>). Verified against real headers on macOS/x86_64,\n   Linux/x86_64, and Linux/aarch64 -- the Linux values are identical across\n   x86_64 and aarch64 (termios bits are arch-invariant on Linux except a\n   handful of exotic ports not targeted by CCCC). */\n#ifdef __APPLE__\n#define VEOF     0\n#define VEOL     1\n#define VEOL2    2\n#define VERASE   3\n#define VWERASE  4\n#define VKILL    5\n#define VREPRINT 6\n#define VINTR    8\n#define VQUIT    9\n#define VSUSP    10\n#define VDSUSP   11\n#define VSTART   12\n#define VSTOP    13\n#define VLNEXT   14\n#define VDISCARD 15\n#define VMIN     16\n#define VTIME    17\n\n#define IGNBRK  0x00000001\n#define BRKINT  0x00000002\n#define IGNPAR  0x00000004\n#define PARMRK  0x00000008\n#define INPCK   0x00000010\n#define ISTRIP  0x00000020\n#define INLCR   0x00000040\n#define IGNCR   0x00000080\n#define ICRNL   0x00000100\n#define IXON    0x00000200\n#define IXOFF   0x00000400\n#define IXANY   0x00000800\n\n#define OPOST   0x00000001\n#define ONLCR   0x00000002\n#define OCRNL   0x00000010\n#define ONOCR   0x00000020\n#define ONLRET  0x00000040\n\n#define CS5     0x00000000\n#define CS6     0x00000100\n#define CS7     0x00000200\n#define CS8     0x00000300\n#define CSTOPB  0x00000400\n#define CREAD   0x00000800\n#define PARENB  0x00001000\n#define PARODD  0x00002000\n#define HUPCL   0x00004000\n#define CLOCAL  0x00008000\n\n#define ECHO    0x00000008\n#define ECHOE   0x00000002\n#define ECHOK   0x00000004\n#define ECHONL  0x00000010\n#define ICANON  0x00000100\n#define IEXTEN  0x00000400\n#define ISIG    0x00000080\n#define NOFLSH  0x80000000\n#define TOSTOP  0x00400000\n\n#define B0       0\n#define B9600    9600\n#define B19200   19200\n#define B38400   38400\n#define B57600   57600\n#define B115200  115200\n#define B230400  230400\n#else\n#define VEOF     4\n#define VEOL     11\n#define VEOL2    16\n#define VERASE   2\n#define VWERASE  14\n#define VKILL    3\n#define VREPRINT 12\n#define VINTR    0\n#define VQUIT    1\n#define VSUSP    10\n#define VSTART   8\n#define VSTOP    9\n#define VLNEXT   15\n#define VDISCARD 13\n#define VMIN     6\n#define VTIME    5\n\n#define IGNBRK  0000001\n#define BRKINT  0000002\n#define IGNPAR  0000004\n#define PARMRK  0000010\n#define INPCK   0000020\n#define ISTRIP  0000040\n#define INLCR   0000100\n#define IGNCR   0000200\n#define ICRNL   0000400\n#define IXON    0002000\n#define IXOFF   0010000\n#define IXANY   0004000\n\n#define OPOST   0000001\n#define ONLCR   0000004\n#define OCRNL   0000010\n#define ONOCR   0000020\n#define ONLRET  0000040\n\n#define CS5     0000000\n#define CS6     0000020\n#define CS7     0000040\n#define CS8     0000060\n#define CSTOPB  0000100\n#define CREAD   0000200\n#define PARENB  0000400\n#define PARODD  0001000\n#define HUPCL   0002000\n#define CLOCAL  0004000\n\n#define ECHO    0000010\n#define ECHOE   0000020\n#define ECHOK   0000040\n#define ECHONL  0000100\n#define ICANON  0000002\n#define IEXTEN  0100000\n#define ISIG    0000001\n#define NOFLSH  0000200\n#define TOSTOP  0000400\n\n#define B0       0000000\n#define B9600    0000015\n#define B19200   0000016\n#define B38400   0000017\n#define B57600   0010001\n#define B115200  0010002\n#define B230400  0010003\n#endif\n\nextern int tcgetattr(int fildes, struct termios *termios_p);\nextern int tcsetattr(int fildes, int optional_actions,\n                     const struct termios *termios_p);\n\n/* Line control */\n#define TCIFLUSH  0\n#define TCOFLUSH  1\n#define TCIOFLUSH 2\n\n#define TCOOFF 0\n#define TCOON  1\n#define TCIOFF 2\n#define TCION  3\n\nextern speed_t cfgetispeed(const struct termios *termios_p);\nextern speed_t cfgetospeed(const struct termios *termios_p);\nextern int cfsetispeed(struct termios *termios_p, speed_t speed);\nextern int cfsetospeed(struct termios *termios_p, speed_t speed);\nextern int cfsetspeed(struct termios *termios_p, speed_t speed);\nextern void cfmakeraw(struct termios *termios_p);\nextern int tcdrain(int fildes);\nextern int tcflow(int fildes, int action);\nextern int tcflush(int fildes, int queue_selector);\nextern int tcsendbreak(int fildes, int duration);\n\n#endif /* __TERMIOS_H */\n";
static char __builtin_testing_h[29979] = "/*!\n * @file testing.h\n * @brief CCCC Test Framework \342\200\224 assertion API injected in --testing mode.\n *\n * This header provides macros and underlying FFI-callable builtins for writing\n * self-verifying test programs.  It is automatically injected when CCCC is\n * invoked with the @c --testing flag and should not be included directly.\n *\n * A test passes if it exits with code 42.\n *\n * ## Usage\n *\n * @code\n * int main(void) {\n *     AssertEq(1 + 1, 2);\n *     AssertStrEq(\"hello\", \"hello\");\n *     AssertNull(NULL);\n *     return 42;\n * }\n * @endcode\n *\n * Each assertion macro expands to a call to an FFI-callable @c __builtin_assert_*\n * function.  On failure, the builtin prints the source location and expression,\n * then terminates with a failure exit code.\n */\n\n#pragma once\n\n// ============================================================================\n// Underlying FFI-callable assertion functions\n// ============================================================================\n\n/*!\n * @function __builtin_assert\n * @abstract Assert that a condition is true.\n * @param cond The boolean condition (must be non-zero to pass).\n * @param expr Stringified expression for diagnostic output.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c Assert and @c AssertTrue.\n */\nvoid __builtin_assert(int cond, const char *expr, const char *file, int line);\n\n/*!\n * @function __builtin_assert_false\n * @abstract Assert that a condition is false.\n * @param cond The boolean condition (must be zero to pass).\n * @param expr Stringified expression for diagnostic output.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertFalse.\n */\nvoid __builtin_assert_false(int cond, const char *expr, const char *file, int line);\n\n/*!\n * @function __builtin_assert_fail\n * @abstract Unconditionally fail a test.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertFail.\n */\nvoid __builtin_assert_fail(const char *file, int line);\n\n/*!\n * @function __builtin_assert_fail_msg\n * @abstract Unconditionally fail a test with a custom message.\n * @param msg Custom failure message.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertFailMsg.\n */\nvoid __builtin_assert_fail_msg(const char *msg, const char *file, int line);\n\n/*!\n * @function __builtin_assert_eq\n * @abstract Assert that two integers are equal.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n * @param as Stringified left expression.\n * @param bs Stringified right expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertEq.\n */\nvoid __builtin_assert_eq(long long a, long long b, const char *as, const char *bs,\n                     const char *file, int line);\n\n/*!\n * @function __builtin_assert_neq\n * @abstract Assert that two integers are not equal.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n * @param as Stringified left expression.\n * @param bs Stringified right expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertNeq.\n */\nvoid __builtin_assert_neq(long long a, long long b, const char *as, const char *bs,\n                      const char *file, int line);\n\n/*!\n * @function __builtin_assert_gt\n * @abstract Assert that one integer is greater than another.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n * @param as Stringified left expression.\n * @param bs Stringified right expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertGt.\n */\nvoid __builtin_assert_gt(long long a, long long b, const char *as, const char *bs,\n                     const char *file, int line);\n\n/*!\n * @function __builtin_assert_lt\n * @abstract Assert that one integer is less than another.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n * @param as Stringified left expression.\n * @param bs Stringified right expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertLt.\n */\nvoid __builtin_assert_lt(long long a, long long b, const char *as, const char *bs,\n                     const char *file, int line);\n\n/*!\n * @function __builtin_assert_ge\n * @abstract Assert that one integer is greater than or equal to another.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n * @param as Stringified left expression.\n * @param bs Stringified right expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertGe.\n */\nvoid __builtin_assert_ge(long long a, long long b, const char *as, const char *bs,\n                     const char *file, int line);\n\n/*!\n * @function __builtin_assert_le\n * @abstract Assert that one integer is less than or equal to another.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n * @param as Stringified left expression.\n * @param bs Stringified right expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertLe.\n */\nvoid __builtin_assert_le(long long a, long long b, const char *as, const char *bs,\n                     const char *file, int line);\n\n/*!\n * @function __builtin_assert_within\n * @abstract Assert that an integer is within a delta of an expected value.\n * @param delta Maximum allowed absolute difference.\n * @param expected Expected value.\n * @param actual Actual value.\n * @param ds Stringified delta expression.\n * @param es Stringified expected expression.\n * @param as Stringified actual expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertWithin.  Passes if\n *             |actual - expected| <= delta.\n */\nvoid __builtin_assert_within(long long delta, long long expected, long long actual,\n                         const char *ds, const char *es, const char *as,\n                         const char *file, int line);\n\n/*!\n * @function __builtin_assert_null\n * @abstract Assert that a pointer is NULL.\n * @param p The pointer to check.\n * @param ps Stringified pointer expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertNull.\n */\nvoid __builtin_assert_null(const void *p, const char *ps,\n                       const char *file, int line);\n\n/*!\n * @function __builtin_assert_not_null\n * @abstract Assert that a pointer is not NULL.\n * @param p The pointer to check.\n * @param ps Stringified pointer expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertNotNull.\n */\nvoid __builtin_assert_not_null(const void *p, const char *ps,\n                           const char *file, int line);\n\n/*!\n * @function __builtin_assert_streq\n * @abstract Assert that two C strings are equal (full strcmp).\n * @param a Expected string.\n * @param b Actual string.\n * @param as Stringified expected expression.\n * @param bs Stringified actual expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertStrEq.  Uses strcmp for comparison.\n */\nvoid __builtin_assert_streq(const char *a, const char *b,\n                        const char *as, const char *bs,\n                        const char *file, int line);\n\n/*!\n * @function __builtin_assert_streq_len\n * @abstract Assert that two C strings are equal up to a given length.\n * @param a Expected string.\n * @param b Actual string.\n * @param len Maximum number of characters to compare.\n * @param as Stringified expected expression.\n * @param bs Stringified actual expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertStrEqLen.  Uses strncmp for comparison.\n */\nvoid __builtin_assert_streq_len(const char *a, const char *b, long long len,\n                            const char *as, const char *bs,\n                            const char *file, int line);\n\n/*!\n * @function __builtin_assert_mem_eq\n * @abstract Assert that two memory regions are byte-identical.\n * @param expected Pointer to expected data.\n * @param actual Pointer to actual data.\n * @param len Number of bytes to compare.\n * @param es Stringified expected expression.\n * @param as Stringified actual expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertMemEq.  Uses memcmp for comparison.\n */\nvoid __builtin_assert_mem_eq(const void *expected, const void *actual, long long len,\n                         const char *es, const char *as,\n                         const char *file, int line);\n\n/*!\n * @function __builtin_assert_float_within\n * @abstract Assert that a float is within a delta of an expected value.\n * @param delta Maximum allowed absolute difference.\n * @param expected Expected value.\n * @param actual Actual value.\n * @param ds Stringified delta expression.\n * @param es Stringified expected expression.\n * @param as Stringified actual expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertFloatWithin and @c AssertFloatEq.\n *             Passes if |actual - expected| <= delta.\n */\nvoid __builtin_assert_float_within(double delta, double expected, double actual,\n                               const char *ds, const char *es, const char *as,\n                               const char *file, int line);\n\n/*!\n * @function __builtin_assert_double_within\n * @abstract Assert that a double is within a delta of an expected value.\n * @param delta Maximum allowed absolute difference.\n * @param expected Expected value.\n * @param actual Actual value.\n * @param ds Stringified delta expression.\n * @param es Stringified expected expression.\n * @param as Stringified actual expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertDoubleWithin and @c AssertDoubleEq.\n *             Passes if |actual - expected| <= delta.\n */\nvoid __builtin_assert_double_within(double delta, double expected, double actual,\n                                const char *ds, const char *es, const char *as,\n                                const char *file, int line);\n\n/*!\n * @function __builtin_assert_bits\n * @abstract Assert that specific bits match between expected and actual values.\n * @param mask Bit mask to apply.\n * @param expected Expected masked value.\n * @param actual Actual value to mask and compare.\n * @param ms Stringified mask expression.\n * @param es Stringified expected expression.\n * @param as Stringified actual expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertBits.  Passes if\n *             (actual & mask) == (expected & mask).\n */\nvoid __builtin_assert_bits(long long mask, long long expected, long long actual,\n                       const char *ms, const char *es, const char *as,\n                       const char *file, int line);\n\n/*!\n * @function __builtin_assert_bit_high\n * @abstract Assert that a specific bit is set (high/1).\n * @param bit Zero-based bit index.\n * @param actual Value to inspect.\n * @param bs Stringified bit index expression.\n * @param as Stringified actual expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertBitHigh.  Passes if (actual >> bit) & 1.\n */\nvoid __builtin_assert_bit_high(int bit, long long actual,\n                           const char *bs, const char *as,\n                           const char *file, int line);\n\n/*!\n * @function __builtin_assert_bit_low\n * @abstract Assert that a specific bit is clear (low/0).\n * @param bit Zero-based bit index.\n * @param actual Value to inspect.\n * @param bs Stringified bit index expression.\n * @param as Stringified actual expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertBitLow.  Passes if !((actual >> bit) & 1).\n */\nvoid __builtin_assert_bit_low(int bit, long long actual,\n                          const char *bs, const char *as,\n                          const char *file, int line);\n\n/*!\n * @function __builtin_assert_eq_array\n * @abstract Assert that two arrays are element-by-element equal.\n * @param expected Pointer to expected array.\n * @param actual Pointer to actual array.\n * @param elem_size Size of each element in bytes.\n * @param count Number of elements to compare.\n * @param es Stringified expected expression.\n * @param as Stringified actual expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertArrayEq.  Uses memcmp internally.\n */\nvoid __builtin_assert_eq_array(const void *expected, const void *actual,\n                           long long elem_size, long long count,\n                           const char *es, const char *as,\n                           const char *file, int line);\n\n// ============================================================================\n// Message-appending variants\n// ============================================================================\n\n/*!\n * @function __builtin_assert_msg\n * @abstract Assert a condition is true with a custom message.\n * @param cond The boolean condition (must be non-zero to pass).\n * @param expr Stringified expression for diagnostic output.\n * @param msg Custom failure message.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertMsg and @c AssertTrueMsg.\n */\nvoid __builtin_assert_msg(int cond, const char *expr, const char *msg,\n                      const char *file, int line);\n\n/*!\n * @function __builtin_assert_eq_msg\n * @abstract Assert two integers are equal with a custom message.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n * @param as Stringified left expression.\n * @param bs Stringified right expression.\n * @param msg Custom failure message.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertEqMsg.\n */\nvoid __builtin_assert_eq_msg(long long a, long long b,\n                         const char *as, const char *bs, const char *msg,\n                         const char *file, int line);\n\n/*!\n * @function __builtin_assert_streq_msg\n * @abstract Assert two C strings are equal with a custom message.\n * @param a Expected string.\n * @param b Actual string.\n * @param as Stringified expected expression.\n * @param bs Stringified actual expression.\n * @param msg Custom failure message.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertStrEqMsg.\n */\nvoid __builtin_assert_streq_msg(const char *a, const char *b,\n                            const char *as, const char *bs, const char *msg,\n                            const char *file, int line);\n\n/*!\n * @function __builtin_assert_null_msg\n * @abstract Assert a pointer is NULL with a custom message.\n * @param p The pointer to check.\n * @param ps Stringified pointer expression.\n * @param msg Custom failure message.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertNullMsg.\n */\nvoid __builtin_assert_null_msg(const void *p, const char *ps, const char *msg,\n                           const char *file, int line);\n\n/*!\n * @function __builtin_assert_not_null_msg\n * @abstract Assert a pointer is not NULL with a custom message.\n * @param p The pointer to check.\n * @param ps Stringified pointer expression.\n * @param msg Custom failure message.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertNotNullMsg.\n */\nvoid __builtin_assert_not_null_msg(const void *p, const char *ps, const char *msg,\n                               const char *file, int line);\n\n/*!\n * @function __builtin_assert_bits_msg\n * @abstract Assert specific bits match with a custom message.\n * @param mask Bit mask to apply.\n * @param expected Expected masked value.\n * @param actual Actual value to mask and compare.\n * @param ms Stringified mask expression.\n * @param es Stringified expected expression.\n * @param as Stringified actual expression.\n * @param msg Custom failure message.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertBitsMsg.  Passes if\n *             (actual & mask) == (expected & mask).\n */\nvoid __builtin_assert_bits_msg(long long mask, long long expected, long long actual,\n                           const char *ms, const char *es, const char *as,\n                           const char *msg, const char *file, int line);\n\n// ============================================================================\n// Basic Validity Assertions\n// ============================================================================\n\n/*!\n * @define Assert\n * @abstract Assert that a condition is true.\n * @param cond The condition to test.\n * @discussion Expands to __builtin_assert with stringified expression,\n *             source file, and line.  Equivalent to @c AssertTrue.\n */\n#define Assert(cond) \\\n    __builtin_assert(!!(cond), #cond, __FILE__, __LINE__)\n\n/*!\n * @define AssertTrue\n * @abstract Assert that a condition is true (alias for Assert).\n * @param cond The condition to test.\n */\n#define AssertTrue(cond) \\\n    Assert(cond)\n\n/*!\n * @define AssertFalse\n * @abstract Assert that a condition is false.\n * @param cond The condition to test (must evaluate to zero).\n */\n#define AssertFalse(cond) \\\n    __builtin_assert_false(!!(cond), #cond, __FILE__, __LINE__)\n\n/*!\n * @define AssertFail\n * @abstract Unconditionally fail the current test.\n */\n#define AssertFail() \\\n    __builtin_assert_fail(__FILE__, __LINE__)\n\n/*!\n * @define AssertFailMsg\n * @abstract Unconditionally fail the current test with a custom message.\n * @param msg Custom failure message.\n */\n#define AssertFailMsg(msg) \\\n    __builtin_assert_fail_msg(msg, __FILE__, __LINE__)\n\n// ============================================================================\n// Numerical Assertions: Integers\n// ============================================================================\n\n/*!\n * @define AssertEq\n * @abstract Assert two integers are equal.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n */\n#define AssertEq(a, b) \\\n    __builtin_assert_eq((long long)(a), (long long)(b), #a, #b, __FILE__, __LINE__)\n\n/*!\n * @define AssertNeq\n * @abstract Assert two integers are not equal.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n */\n#define AssertNeq(a, b) \\\n    __builtin_assert_neq((long long)(a), (long long)(b), #a, #b, __FILE__, __LINE__)\n\n/*!\n * @define AssertGt\n * @abstract Assert one integer is greater than another.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n */\n#define AssertGt(a, b) \\\n    __builtin_assert_gt((long long)(a), (long long)(b), #a, #b, __FILE__, __LINE__)\n\n/*!\n * @define AssertLt\n * @abstract Assert one integer is less than another.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n */\n#define AssertLt(a, b) \\\n    __builtin_assert_lt((long long)(a), (long long)(b), #a, #b, __FILE__, __LINE__)\n\n/*!\n * @define AssertGe\n * @abstract Assert one integer is greater than or equal to another.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n */\n#define AssertGe(a, b) \\\n    __builtin_assert_ge((long long)(a), (long long)(b), #a, #b, __FILE__, __LINE__)\n\n/*!\n * @define AssertLe\n * @abstract Assert one integer is less than or equal to another.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n */\n#define AssertLe(a, b) \\\n    __builtin_assert_le((long long)(a), (long long)(b), #a, #b, __FILE__, __LINE__)\n\n/*!\n * @define AssertWithin\n * @abstract Assert an integer is within a delta of an expected value.\n * @param delta Maximum allowed absolute difference.\n * @param expected Expected value.\n * @param actual Actual value.\n * @discussion Passes if |actual - expected| <= delta.\n */\n#define AssertWithin(delta, expected, actual) \\\n    __builtin_assert_within((long long)(delta), (long long)(expected), (long long)(actual), \\\n                        #delta, #expected, #actual, __FILE__, __LINE__)\n\n// ============================================================================\n// Numerical Assertions: Bitwise\n// ============================================================================\n\n/*!\n * @define AssertBits\n * @abstract Assert that specific bits match between expected and actual values.\n * @param mask Bit mask to apply.\n * @param expected Expected masked value.\n * @param actual Actual value to mask and compare.\n * @discussion Passes if (actual & mask) == (expected & mask).\n */\n#define AssertBits(mask, expected, actual) \\\n    __builtin_assert_bits((long long)(mask), (long long)(expected), (long long)(actual), \\\n                      #mask, #expected, #actual, __FILE__, __LINE__)\n\n/*!\n * @define AssertBitHigh\n * @abstract Assert that a specific bit is set (high/1).\n * @param bit Zero-based bit index.\n * @param actual Value to inspect.\n * @discussion Passes if (actual >> bit) & 1.\n */\n#define AssertBitHigh(bit, actual) \\\n    __builtin_assert_bit_high((int)(bit), (long long)(actual), \\\n                          #bit, #actual, __FILE__, __LINE__)\n\n/*!\n * @define AssertBitLow\n * @abstract Assert that a specific bit is clear (low/0).\n * @param bit Zero-based bit index.\n * @param actual Value to inspect.\n * @discussion Passes if !((actual >> bit) & 1).\n */\n#define AssertBitLow(bit, actual) \\\n    __builtin_assert_bit_low((int)(bit), (long long)(actual), \\\n                         #bit, #actual, __FILE__, __LINE__)\n\n// ============================================================================\n// Numerical Assertions: Floats / Doubles\n// ============================================================================\n\n/*!\n * @define AssertFloatWithin\n * @abstract Assert a float is within a delta of an expected value.\n * @param delta Maximum allowed absolute difference.\n * @param expected Expected value.\n * @param actual Actual value.\n */\n#define AssertFloatWithin(delta, expected, actual) \\\n    __builtin_assert_float_within((double)(delta), (double)(expected), (double)(actual), \\\n                              #delta, #expected, #actual, __FILE__, __LINE__)\n\n/*!\n * @define AssertDoubleWithin\n * @abstract Assert a double is within a delta of an expected value.\n * @param delta Maximum allowed absolute difference.\n * @param expected Expected value.\n * @param actual Actual value.\n */\n#define AssertDoubleWithin(delta, expected, actual) \\\n    __builtin_assert_double_within((double)(delta), (double)(expected), (double)(actual), \\\n                               #delta, #expected, #actual, __FILE__, __LINE__)\n\n/*!\n * @define AssertFloatEq\n * @abstract Assert two floats are approximately equal (default epsilon 1e-6).\n * @param expected Expected value.\n * @param actual Actual value.\n * @discussion Uses a default delta of 1e-6.\n */\n#define AssertFloatEq(expected, actual) \\\n    __builtin_assert_float_within(1e-6, (double)(expected), (double)(actual), \\\n                              #expected, #expected, #actual, __FILE__, __LINE__)\n\n/*!\n * @define AssertDoubleEq\n * @abstract Assert two doubles are approximately equal (default epsilon 1e-15).\n * @param expected Expected value.\n * @param actual Actual value.\n * @discussion Uses a default delta of 1e-15.\n */\n#define AssertDoubleEq(expected, actual) \\\n    __builtin_assert_double_within(1e-15, (double)(expected), (double)(actual), \\\n                               #expected, #expected, #actual, __FILE__, __LINE__)\n\n// ============================================================================\n// Pointer Assertions\n// ============================================================================\n\n/*!\n * @define AssertNull\n * @abstract Assert a pointer is NULL.\n * @param p The pointer to check.\n */\n#define AssertNull(p) \\\n    __builtin_assert_null((const void *)(p), #p, __FILE__, __LINE__)\n\n/*!\n * @define AssertNotNull\n * @abstract Assert a pointer is not NULL.\n * @param p The pointer to check.\n */\n#define AssertNotNull(p) \\\n    __builtin_assert_not_null((const void *)(p), #p, __FILE__, __LINE__)\n\n// ============================================================================\n// String Assertions\n// ============================================================================\n\n/*!\n * @define AssertStrEq\n * @abstract Assert two C strings are equal.\n * @param a Expected string.\n * @param b Actual string.\n */\n#define AssertStrEq(a, b) \\\n    __builtin_assert_streq((a), (b), #a, #b, __FILE__, __LINE__)\n\n/*!\n * @define AssertStrEqLen\n * @abstract Assert two C strings are equal up to a given length.\n * @param a Expected string.\n * @param b Actual string.\n * @param len Maximum number of characters to compare.\n */\n#define AssertStrEqLen(a, b, len) \\\n    __builtin_assert_streq_len((a), (b), (long long)(len), #a, #b, __FILE__, __LINE__)\n\n// ============================================================================\n// Memory Assertions\n// ============================================================================\n\n/*!\n * @define AssertMemEq\n * @abstract Assert two memory regions are byte-identical.\n * @param expected Pointer to expected data.\n * @param actual Pointer to actual data.\n * @param len Number of bytes to compare.\n */\n#define AssertMemEq(expected, actual, len) \\\n    __builtin_assert_mem_eq((const void *)(expected), (const void *)(actual), \\\n                        (long long)(len), #expected, #actual, __FILE__, __LINE__)\n\n// ============================================================================\n// Array Assertions\n// ============================================================================\n\n/*!\n * @define AssertArrayEq\n * @abstract Assert two arrays are element-by-element equal.\n * @param expected Pointer to expected array.\n * @param actual Pointer to actual array.\n * @param count Number of elements (element size is inferred).\n * @discussion Uses sizeof((expected)[0]) to infer element size.\n */\n#define AssertArrayEq(expected, actual, count) \\\n    __builtin_assert_eq_array((const void *)(expected), (const void *)(actual), \\\n                          (long long)sizeof((expected)[0]), (long long)(count), \\\n                          #expected, #actual, __FILE__, __LINE__)\n\n/*!\n * @define AssertEachEq\n * @abstract Assert each element of an array equals a scalar expected value.\n * @param expected Scalar expected value.\n * @param actual Array expression.\n * @param count Number of elements.\n * @discussion Iterates over the array and compares each element individually.\n *             On failure, reports the failing index as \"[i]\".\n */\n#define AssertEachEq(expected, actual, count) \\\n    do { \\\n        long long _cccc_i_; \\\n        for (_cccc_i_ = 0; _cccc_i_ < (long long)(count); _cccc_i_++) \\\n            __builtin_assert_eq((long long)((expected)), \\\n                           (long long)(((const typeof((actual)[0])*)(actual))[_cccc_i_]), \\\n                           #expected, #actual \"[i]\", \\\n                           __FILE__, __LINE__); \\\n    } while (0)\n\n// ============================================================================\n// Message-appending variants (_msg suffix)\n// ============================================================================\n\n/*!\n * @define AssertMsg\n * @abstract Assert a condition is true with a custom message.\n * @param cond The condition to test.\n * @param msg Custom failure message.\n */\n#define AssertMsg(cond, msg) \\\n    __builtin_assert_msg(!!(cond), #cond, msg, __FILE__, __LINE__)\n\n/*!\n * @define AssertTrueMsg\n * @abstract Assert a condition is true with a custom message (alias for AssertMsg).\n * @param cond The condition to test.\n * @param msg Custom failure message.\n */\n#define AssertTrueMsg(cond, msg) \\\n    AssertMsg(cond, msg)\n\n/*!\n * @define AssertFalseMsg\n * @abstract Assert a condition is false with a custom message.\n * @param cond The condition to test.\n * @param msg Custom failure message.\n */\n#define AssertFalseMsg(cond, msg) \\\n    __builtin_assert_msg(!(cond), #cond, msg, __FILE__, __LINE__)\n\n/*!\n * @define AssertEqMsg\n * @abstract Assert two integers are equal with a custom message.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n * @param msg Custom failure message.\n */\n#define AssertEqMsg(a, b, msg) \\\n    __builtin_assert_eq_msg((long long)(a), (long long)(b), #a, #b, msg, \\\n                        __FILE__, __LINE__)\n\n/*!\n * @define AssertStrEqMsg\n * @abstract Assert two C strings are equal with a custom message.\n * @param a Expected string.\n * @param b Actual string.\n * @param msg Custom failure message.\n */\n#define AssertStrEqMsg(a, b, msg) \\\n    __builtin_assert_streq_msg((a), (b), #a, #b, msg, __FILE__, __LINE__)\n\n/*!\n * @define AssertNullMsg\n * @abstract Assert a pointer is NULL with a custom message.\n * @param p The pointer to check.\n * @param msg Custom failure message.\n */\n#define AssertNullMsg(p, msg) \\\n    __builtin_assert_null_msg((const void *)(p), #p, msg, __FILE__, __LINE__)\n\n/*!\n * @define AssertNotNullMsg\n * @abstract Assert a pointer is not NULL with a custom message.\n * @param p The pointer to check.\n * @param msg Custom failure message.\n */\n#define AssertNotNullMsg(p, msg) \\\n    __builtin_assert_not_null_msg((const void *)(p), #p, msg, __FILE__, __LINE__)\n\n/*!\n * @define AssertBitsMsg\n * @abstract Assert specific bits match with a custom message.\n * @param mask Bit mask to apply.\n * @param expected Expected masked value.\n * @param actual Actual value to mask and compare.\n * @param msg Custom failure message.\n */\n#define AssertBitsMsg(mask, expected, actual, msg) \\\n    __builtin_assert_bits_msg((long long)(mask), (long long)(expected), (long long)(actual), \\\n                          #mask, #expected, #actual, msg, __FILE__, __LINE__)\n";
static char __builtin_tgmath_h[1690] = "/* tgmath.h - type-generic math macros for CCCC */\n\n#ifndef __TGMATH_H\n#define __TGMATH_H\n\n#include \"math.h\"\n#include \"complex.h\"\n\n#define __cccc_tg_unary(x, fd, ff, fl) _Generic((x), \\\n    long double: fl, \\\n    float: ff, \\\n    default: fd)(x)\n\n#define __cccc_tg_binary(x, y, fd, ff, fl) _Generic(((x) + (y)), \\\n    long double: fl, \\\n    float: ff, \\\n    default: fd)(x, y)\n\n#define __cccc_tg_real_or_complex_abs(x) _Generic((x), \\\n    long double _Complex: cabsl(x), \\\n    double _Complex: cabs(x), \\\n    float _Complex: cabsf(x), \\\n    long double: fabsl(x), \\\n    float: fabsf(x), \\\n    default: fabs(x))\n\n#define acos(x) __cccc_tg_unary((x), acos, acosf, acosl)\n#define asin(x) __cccc_tg_unary((x), asin, asinf, asinl)\n#define atan(x) __cccc_tg_unary((x), atan, atanf, atanl)\n#define cos(x) __cccc_tg_unary((x), cos, cosf, cosl)\n#define sin(x) __cccc_tg_unary((x), sin, sinf, sinl)\n#define tan(x) __cccc_tg_unary((x), tan, tanf, tanl)\n#define exp(x) __cccc_tg_unary((x), exp, expf, expl)\n#define log(x) __cccc_tg_unary((x), log, logf, logl)\n#define sqrt(x) __cccc_tg_unary((x), sqrt, sqrtf, sqrtl)\n#define fabs(x) __cccc_tg_real_or_complex_abs((x))\n#define floor(x) __cccc_tg_unary((x), floor, floorf, floorl)\n#define ceil(x) __cccc_tg_unary((x), ceil, ceilf, ceill)\n#define trunc(x) __cccc_tg_unary((x), trunc, truncf, truncl)\n#define round(x) __cccc_tg_unary((x), round, roundf, roundl)\n#define pow(x, y) __cccc_tg_binary((x), (y), pow, powf, powl)\n#define fmod(x, y) __cccc_tg_binary((x), (y), fmod, fmodf, fmodl)\n#define atan2(x, y) __cccc_tg_binary((x), (y), atan2, atan2f, atan2l)\n#define hypot(x, y) __cccc_tg_binary((x), (y), hypot, hypotf, hypotl)\n\n#endif /* __TGMATH_H */\n";
static char __builtin_threads_h[2523] = "#ifndef __THREADS_H\n#define __THREADS_H\n\n#ifdef _WIN32\n#error \"<threads.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"pthread.h\"\n#include \"time.h\"\n#include \"errno.h\"\n\n/* C11 thread type backed by the existing pthread VM implementation */\ntypedef pthread_t thrd_t;\n\n/* Thread-specific storage key */\ntypedef pthread_key_t tss_t;\ntypedef void (*tss_dtor_t)(void *);\n\n/* Mutex: store the C11 type flag so mtx_init can configure appropriately.\n   Layout mirrors CCCCUserMutex (void *__handle, long __state) plus an int\n   type tag; the host mutex is lazily allocated on first lock. */\ntypedef struct {\n    void *__handle;\n    long  __state;\n    int   __type;\n} mtx_t;\n\n/* Condition variable backed by pthread cond */\ntypedef struct {\n    void *__handle;\n    long  __state;\n} cnd_t;\n\n/* Thread start function returning int (differs from pthread's void*) */\ntypedef int (*thrd_start_t)(void *);\n\n/* Mutex type flags */\nenum {\n    mtx_plain     = 0,\n    mtx_recursive = 1,\n    mtx_timed     = 2,\n};\n\n/* Return codes */\nenum {\n    thrd_success  = 0,\n    thrd_error    = 1,\n    thrd_timedout = ETIMEDOUT,\n    thrd_busy     = EBUSY,\n    thrd_nomem    = ENOMEM,\n};\n\n/* call_once: under the GIL, bytecode execution is serialised so a simple\n   flag check + call is atomic from the VM's perspective. */\ntypedef _Atomic int once_flag;\n#define ONCE_FLAG_INIT 0\n\n#define call_once(flag, func) \\\n    do { if (!(*(flag))) { *(flag) = 1; (func)(); } } while (0)\n\n/* ---- Thread lifecycle ---- */\nint    thrd_create(thrd_t *thr, thrd_start_t func, void *arg);\nint    thrd_join(thrd_t thr, int *res);\nvoid   thrd_exit(int res);\nint    thrd_detach(thrd_t thr);\nvoid   thrd_yield(void);\nint    thrd_sleep(const struct timespec *duration, struct timespec *remaining);\nthrd_t thrd_current(void);\nint    thrd_equal(thrd_t a, thrd_t b);\n\n/* ---- Mutex ---- */\nint  mtx_init(mtx_t *mtx, int type);\nint  mtx_lock(mtx_t *mtx);\nint  mtx_trylock(mtx_t *mtx);\nint  mtx_timedlock(mtx_t *mtx, const struct timespec *ts);\nint  mtx_unlock(mtx_t *mtx);\nvoid mtx_destroy(mtx_t *mtx);\n\n/* ---- Condition variable ---- */\nint  cnd_init(cnd_t *cond);\nint  cnd_wait(cnd_t *cond, mtx_t *mtx);\nint  cnd_signal(cnd_t *cond);\nint  cnd_broadcast(cnd_t *cond);\nint  cnd_timedwait(cnd_t *cond, mtx_t *mtx, const struct timespec *ts);\nvoid cnd_destroy(cnd_t *cond);\n\n/* ---- Thread-specific storage ---- */\nint   tss_create(tss_t *key, tss_dtor_t dtor);\nvoid *tss_get(tss_t key);\nint   tss_set(tss_t key, void *val);\nvoid  tss_delete(tss_t key);\n\n#endif\n";
static char __builtin_time_h[1320] = "/* time.h - time functions for CCCC C compiler */\n\n#ifndef __TIME_H\n#define __TIME_H\n\n#include \"stddef.h\"\n\ntypedef long clock_t;\ntypedef long time_t;\n\n#define CLOCKS_PER_SEC 1000000\n\nstruct timespec {\n    time_t tv_sec;\n    long tv_nsec;\n};\n\n#define TIME_UTC 1\n\nstruct tm {\n    int tm_sec;\n    int tm_min;\n    int tm_hour;\n    int tm_mday;\n    int tm_mon;\n    int tm_year;\n    int tm_wday;\n    int tm_yday;\n    int tm_isdst;\n    long tm_gmtoff;\n    char *tm_zone;\n};\n\nextern clock_t clock(void);\nextern double difftime(time_t time1, time_t time0);\nextern time_t mktime(struct tm *timeptr);\nextern time_t timegm(struct tm *timeptr);\nextern time_t time(time_t *t);\nextern int timespec_get(struct timespec *ts, int base);\nextern int nanosleep(const struct timespec *req, struct timespec *rem);\n// extern int timespec_getres(struct timespec *ts, int base);\nextern char *asctime(const struct tm *tm); // deprecated\nextern char *ctime(const time_t *timer); // deprecated\nextern struct tm *gmtime(const time_t *timer);\nextern struct tm *gmtime_r(const time_t *timer, struct tm *result);\nextern struct tm *localtime(const time_t *timer);\nextern struct tm *localtime_r(const time_t *timer, struct tm *result);\nextern size_t strftime(char *s, size_t maxsize, const char *format, const struct tm *timeptr);\n\n#endif /* __TIME_H */\n";
static char __builtin_uchar_h[703] = "/* uchar.h - Unicode character conversion declarations for CCCC */\n\n#ifndef __UCHAR_H\n#define __UCHAR_H\n\n#include \"stddef.h\"\n#include \"wchar.h\"\n\ntypedef unsigned char  char8_t;   // C23 \302\2477.28\ntypedef unsigned short char16_t;\ntypedef unsigned int char32_t;\n\nextern size_t mbrtoc8(char8_t *pc8, const char *s, size_t n, mbstate_t *ps);\nextern size_t c8rtomb(char *s, char8_t c8, mbstate_t *ps);\nextern size_t mbrtoc16(char16_t *pc16, const char *s, size_t n, mbstate_t *ps);\nextern size_t c16rtomb(char *s, char16_t c16, mbstate_t *ps);\nextern size_t mbrtoc32(char32_t *pc32, const char *s, size_t n, mbstate_t *ps);\nextern size_t c32rtomb(char *s, char32_t c32, mbstate_t *ps);\n\n#endif /* __UCHAR_H */\n";
static char __builtin_unistd_h[7051] = "/* unistd.h - core POSIX declarations for CCCC */\n\n#ifndef __UNISTD_H\n#define __UNISTD_H\n\n#ifdef _WIN32\n#error \"<unistd.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"stddef.h\"\n#include \"sys/types.h\"\n\n#ifndef _SSIZE_T\ntypedef long ssize_t;\n#define _SSIZE_T\n#endif\n\n#ifndef NULL\n#define NULL ((void*)0)\n#endif\n\n#define STDIN_FILENO 0\n#define STDOUT_FILENO 1\n#define STDERR_FILENO 2\n\n#ifndef SEEK_SET\n#define SEEK_SET 0\n#define SEEK_CUR 1\n#define SEEK_END 2\n#endif\n\n#define F_OK 0\n#define X_OK 1\n#define W_OK 2\n#define R_OK 4\n\nextern ssize_t read(int fd, void *buf, size_t count);\nextern ssize_t write(int fd, const void *buf, size_t count);\nextern int close(int fd);\nextern off_t lseek(int fd, off_t offset, int whence);\nextern int access(const char *path, int amode);\nextern int unlink(const char *path);\nextern int rmdir(const char *path);\nextern int chdir(const char *path);\nextern char *getcwd(char *buf, size_t size);\nextern pid_t getpid(void);\nextern pid_t getppid(void);\nextern unsigned int sleep(unsigned int seconds);\nextern int usleep(unsigned int useconds);\nextern int pipe(int fd[2]);\nextern void _exit(int status);\nextern pid_t fork(void);\nextern int execv(const char *path, char *const argv[]);\nextern int execve(const char *path, char *const argv[], char *const envp[]);\nextern int execl(const char *path, const char *arg, ...);\nextern int execlp(const char *file, const char *arg, ...);\nextern int execle(const char *path, const char *arg, ...);\nextern int execvp(const char *file, char *const argv[]);\nextern int isatty(int fd);\nextern char *ttyname(int fd);\nextern int dup(int fd);\nextern int dup2(int oldfd, int newfd);\nextern int fsync(int fd);\n#ifdef __linux__\n// fdatasync: POSIX, but absent from Darwin's libc entirely -- macOS has no\n// equivalent syscall/libc symbol at all (the closest analog is the fcntl\n// F_FULLFSYNC command, not a drop-in replacement), unlike fsync above.\n// Same gap class as mremap/splice below (#783).\nextern int fdatasync(int fd);\n#endif\nextern int ftruncate(int fd, off_t length);\nextern int truncate(const char *path, off_t length);\nextern long sysconf(int name);\nextern long pathconf(const char *path, int name);\nextern long fpathconf(int fd, int name);\nextern size_t confstr(int name, char *buf, size_t len);\nextern int mkstemp(char *tmpl);\nextern char *mkdtemp(char *tmpl);\n\n/* Positioned I/O */\nextern ssize_t pread(int fd, void *buf, size_t count, off_t offset);\nextern ssize_t pwrite(int fd, const void *buf, size_t count, off_t offset);\n\n/* Ownership and identity */\nextern int fchown(int fd, uid_t owner, gid_t group);\nextern int chown(const char *path, uid_t owner, gid_t group);\nextern uid_t getuid(void);\nextern uid_t geteuid(void);\nextern gid_t getgid(void);\nextern gid_t getegid(void);\nextern int seteuid(uid_t euid);\nextern int setegid(gid_t egid);\nextern int setuid(uid_t uid);\nextern int setgid(gid_t gid);\nextern int getgroups(int gidsetsize, gid_t grouplist[]);\nextern char *getlogin(void);\n\n/* Symbolic links / hard links */\nextern ssize_t readlink(const char *path, char *buf, size_t bufsize);\nextern int symlink(const char *target, const char *linkpath);\nextern int link(const char *path1, const char *path2);\n\n/* Process groups and sessions */\nextern pid_t getpgid(pid_t pid);\nextern int setpgid(pid_t pid, pid_t pgid);\nextern pid_t getpgrp(void);\nextern pid_t setsid(void);\nextern pid_t getsid(pid_t pid);\n\n/* Alarms and signal waiting */\nextern unsigned int alarm(unsigned int seconds);\nextern int pause(void);\n\n/* Misc process/host */\nextern int fchdir(int fd);\nextern int gethostname(char *name, size_t namelen);\nextern int sethostname(const char *name, size_t namelen);\nextern int lchown(const char *path, uid_t owner, gid_t group);\nextern int ttyname_r(int fd, char *buf, size_t buflen);\nextern int getlogin_r(char *name, size_t namesize);\nextern int setgroups(int ngroups, const gid_t *grouplist);\nextern int initgroups(const char *user, gid_t group);\nextern int nice(int incr);\n\n/* Scatter/gather I/O -- struct iovec/readv/writev now live in sys/uio.h,\n * included here so existing code that gets them via <unistd.h> keeps\n * working (#792). */\n#include \"sys/uio.h\"\n\n/* Page size (legacy BSD interface used by some VFS layers) */\nextern int getpagesize(void);\n\n#ifdef __linux__\n// splice: Linux-only zero-copy pipe I/O, same gap class as mremap/fallocate\n// -- SQLite's unix VFS can reference it under Linux-specific config (#731).\nextern ssize_t splice(int fd_in, off_t *off_in, int fd_out, off_t *off_out,\n                      size_t len, unsigned int flags);\n#endif\n\n/* sysconf()/pathconf()/confstr() constants.\n *\n * These are CCCC's own canonical numbering -- NOT the host libc's numbering.\n * sysconf/pathconf/confstr are registered against translating wrapper\n * functions (wrap_sysconf/wrap_pathconf/wrap_fpathconf/wrap_confstr in\n * src/stdlib/posix.c) that map these canonical values to whatever the host\n * libc actually expects before calling through. This keeps compiled .c4\n * bytecode portable across hosts with different _SC_, _PC_, and _CS_\n * numbering (e.g. macOS vs glibc disagree on nearly all of these) and fixes\n * a latent\n * bug where _SC_NPROCESSORS_ONLN used to be hard-coded to the macOS value\n * and passed straight to the host sysconf() unconditionally.\n */\n\n/* _SC_* -- sysconf() names */\n#define _SC_ARG_MAX             1\n#define _SC_CHILD_MAX           2\n#define _SC_CLK_TCK             3\n#define _SC_NGROUPS_MAX         4\n#define _SC_OPEN_MAX            5\n#define _SC_STREAM_MAX          6\n#define _SC_TZNAME_MAX          7\n#define _SC_JOB_CONTROL         8\n#define _SC_SAVED_IDS           9\n#define _SC_VERSION             10\n#define _SC_PAGESIZE            11\n#define _SC_PAGE_SIZE           _SC_PAGESIZE\n#define _SC_NPROCESSORS_CONF    12\n#define _SC_NPROCESSORS_ONLN    13\n#define _SC_PHYS_PAGES          14\n#define _SC_LINE_MAX            15\n#define _SC_RE_DUP_MAX          16\n#define _SC_2_VERSION           17\n#define _SC_XOPEN_VERSION       18\n#define _SC_HOST_NAME_MAX       19\n#define _SC_LOGIN_NAME_MAX      20\n#define _SC_TTY_NAME_MAX        21\n#define _SC_SYMLOOP_MAX         22\n#define _SC_ATEXIT_MAX          23\n#define _SC_IOV_MAX             24\n#define _SC_GETPW_R_SIZE_MAX    25\n#define _SC_GETGR_R_SIZE_MAX    26\n#define _SC_MONOTONIC_CLOCK     27\n\n/* _PC_* -- pathconf()/fpathconf() names */\n#define _PC_LINK_MAX            1\n#define _PC_MAX_CANON           2\n#define _PC_MAX_INPUT           3\n#define _PC_NAME_MAX            4\n#define _PC_PATH_MAX            5\n#define _PC_PIPE_BUF            6\n#define _PC_CHOWN_RESTRICTED    7\n#define _PC_NO_TRUNC            8\n#define _PC_VDISABLE            9\n\n/* _CS_* -- confstr() names */\n#define _CS_PATH                1\n\n/* POSIX/X\\/Open version this CCCC targets (VM-model constants, not derived\n * from the host). Kept in sync with the feature-test macros predefined by\n * the compiler (see init_macros in src/preprocess.c). */\n#define _POSIX_VERSION   200809L\n#define _POSIX2_VERSION  200809L\n#define _XOPEN_VERSION   700\n\n#endif /* __UNISTD_H */\n";
